Translate("esES", "medivh", {
	title = "Medivh",
	subtitle = "El último Guardián de Tirisfal",
	allegiance = "Orden de Tirisfal · Karazhan",
	sections = {
		{
			title = "Resumen",
			text = [=[Medivh fue el último Guardián de {link:tirisfal-glades}Tirisfal{/link}, el campeón secreto al que los magos más sabios del mundo dieron poder para hacer frente a la {link:burning-legion}Legión Ardiente{/link}. Era hijo de la Guardiana {link:aegwynn}Aegwynn{/link} y de Nielas Aran, conjurador de la corte de {link:stormwind-city}Ventormenta{/link}. También era el amigo más querido del rey {link:llane-wrynn}Llane Wrynn{/link} y de sir {link:anduin-lothar}Anduin Lothar{/link}. Sin embargo, el poder que debía proteger {link:azeroth}Azeroth{/link} estaba envenenado antes de que él respirara por primera vez, y fue Medivh quien abrió el camino a la llegada de los orcos.]=],
		},
		{
			title = "Importancia",
			text = [=[Ningún mortal hizo más por traer la era de la guerra. A través de Medivh, el señor demoníaco {link:sargeras}Sargeras{/link} alcanzó el mundo y lanzó a la {link:horde}Horda{/link} contra los reinos {link:humans}humanos{/link}. La {link:first-war}Primera Guerra{/link}, la caída de {link:stormwind-city}Ventormenta{/link} y cada guerra que siguió tienen sus raíces en la torre donde él vivía.]=],
		},
		{
			title = "Un nacimiento envenenado",
			text = [=[{link:aegwynn}Aegwynn{/link} quería que su hijo fuera su heredero, libre del consejo que había intentado gobernarla. No sabía que {link:sargeras}Sargeras{/link} había ocultado su espíritu dentro de ella desde el día en que ella abatió a su avatar. Cuando Medivh fue concebido, el señor demoníaco pasó al niño que aún no había nacido. El muchacho creció brillante y amable, y recorría los bosques del reino con {link:llane-wrynn}Llane{/link} y {link:anduin-lothar}Lothar{/link}. Cuando tenía catorce años, el poder del Guardián despertó en él, y con él la oscuridad que yacía debajo. Medivh cayó en un sueño que ningún sanador pudo romper. Durante años estuvo al cuidado de los clérigos de la {link:northshire-abbey}Abadía de Villanorte{/link}. Cuando despertó, era un hombre adulto, y no dijo nada de lo que había visto en la oscuridad.]=],
		},
		{
			title = "Karazhan",
			text = [=[Medivh hizo su hogar en {link:karazhan}Karazhan{/link}, una torre solitaria en la tierra que hoy se llama {link:deadwind-pass}Paso de la Muerte{/link}. Allí, guiado por la voluntad que vivía dentro de él, tendió la mano a través del vacío hasta un mundo moribundo llamado {red:draenor}Draenor{/red}. Encontró al brujo {link:orcs}orco{/link} {link:gul-dan}Gul'dan{/link}, y juntos abrieron el {link:dark-portal}Portal Oscuro{/link}. El {link:kirin-tor}Kirin Tor{/link} de {link:city-of-dalaran}Dalaran{/link} le envió a un joven aprendiz, {link:khadgar}Khadgar{/link}, que llegó a temer lo que vio en la torre. La semiorca {link:garona}Garona{/link} también llegó a Karazhan como enviada de la {link:horde}Horda{/link}. A través de Khadgar y Garona, la verdad llegó por fin a {link:stormwind-city}Ventormenta{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• En su juventud alzó su poder contra los trols del sur, al lado de {link:llane-wrynn}Llane{/link} y {link:anduin-lothar}Lothar{/link}.
• Abrió el {link:dark-portal}Portal Oscuro{/link} con {link:gul-dan}Gul'dan{/link} y los brujos de Draenor.
• Tomó a {link:khadgar}Khadgar{/link} como aprendiz y le dejó aprender más de lo que pretendía revelar.
• Contempló desde su torre cómo la {link:horde}Horda{/link} quemaba el reino de sus amigos más antiguos.]=],
		},
		{
			title = "Destino",
			text = [=[{link:anduin-lothar}Anduin Lothar{/link} y {link:khadgar}Khadgar{/link} subieron a {link:karazhan}Karazhan{/link} para acabar con la guerra de raíz. Con la ayuda de {link:garona}Garona{/link} se enfrentaron al Guardián, y allí Medivh murió. En el momento de su muerte, {link:gul-dan}Gul'dan{/link} intentó arrancar de su mente moribunda los secretos de la Tumba de {link:sargeras}Sargeras{/link}, y como castigo cayó en un largo estupor. Medivh está muerto. Su torre sigue vacía y silenciosa sobre el {link:deadwind-pass}Paso de la Muerte{/link}, y la gente del {link:duskwood}Bosque del Ocaso{/link} dice que en sus ventanas aún arden luces extrañas.]=],
		},
		{
			title = "Sin registro",
			text = [=[Lo que Medivh sabía, lo que eligió y lo que {link:sargeras}Sargeras{/link} eligió por él ya no pueden distinguirse. Las crónicas dejan abierta esa pregunta.]=],
		},
	},
	bonds = {
		{ id = "aegwynn", name = "Aegwynn", note = "su madre" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "su amigo de la infancia" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "su amigo, y su verdugo" },
		{ id = "gul-dan", name = "Gul'dan", note = "abrió con él el Portal Oscuro" },
		{ id = "khadgar", name = "Khadgar", note = "su aprendiz" },
	},
})

Translate("esES", "aegwynn", {
	title = "Aegwynn",
	subtitle = "Guardiana de Tirisfal",
	allegiance = "Orden de Tirisfal",
	sections = {
		{
			title = "Resumen",
			text = [=[Aegwynn fue Guardiana de {link:tirisfal-glades}Tirisfal{/link} durante más tiempo del que han existido la mayoría de los reinos. El consejo secreto de Tirisfal, formado por los mayores magos de las tierras {link:humans}humanas{/link} y {link:high-elves}élficas{/link}, la eligió como su campeona contra la {link:burning-legion}Legión Ardiente{/link} y le dio poder y una vida de muchos siglos. Se la recuerda como la más poderosa de todos los Guardianes, y como la que más daño hizo sin quererlo nunca.]=],
		},
		{
			title = "Importancia",
			text = [=[En una sola victoria, Aegwynn asestó el golpe más duro que la Legión sufrió jamás en {link:azeroth}Azeroth{/link}. En ese mismo instante, abrió la puerta a su mayor triunfo. El señor demoníaco {link:sargeras}Sargeras{/link} se ocultó dentro de ella, y a través de ella pasó a su hijo, {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "La Guardiana",
			text = [=[Aegwynn era orgullosa e intrépida, y no quiso servir de títere al consejo. Cazaba demonios dondequiera que caminaran, y llevó el manto durante muchas vidas humanas. En {red:northrend}Rasganorte{/red} encontró demonios que cazaban a los últimos dragones del norte y drenaban su magia. Con la ayuda de los dragones, los destruyó. Entonces el propio {link:sargeras}Sargeras{/link} apareció ante ella en medio de una gran tormenta. Aegwynn luchó contra su avatar y lo mató. Selló su cuerpo destrozado en una antigua sala que se había hundido bajo el mar durante la {link:great-sundering}Gran Fractura{/link}, para que nunca pudiera volver a alzarse. Creyó que el amo de la Legión había sido derrotado. No sabía que su espíritu se había deslizado dentro de ella.]=],
		},
		{
			title = "La heredera del Guardián",
			text = [=[A lo largo de los muchos años que siguieron, Aegwynn se distanció del consejo. Llegó a creer que sus miembros se entrometían en los asuntos de los reyes, y decidió que nunca elegirían al siguiente Guardián. Tomó como consorte a Nielas Aran, conjurador de la corte de {link:stormwind-city}Ventormenta{/link}, y le dio un hijo. Depositó el poder de {link:tirisfal-glades}Tirisfal{/link} dentro del niño, para que despertara cuando alcanzara la mayoría de edad. Después dejó al niño con su padre y se retiró del mundo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Llevó el manto de Guardiana durante muchos siglos y destruyó demonios por todos los {link:eastern-kingdoms}Reinos del Este{/link}.
• Defendió a los dragones de Rasganorte de los cazadores de la Legión.
• Mató al avatar de {link:sargeras}Sargeras{/link} y sepultó su cuerpo bajo el mar.
• Desafió al consejo de {link:tirisfal-glades}Tirisfal{/link} y eligió a su propio heredero.]=],
		},
		{
			title = "Destino",
			text = [=[Aegwynn sobrevivió al hijo que creó. Cuando el {link:dark-portal}Portal Oscuro{/link} se abrió y llegó la {link:horde}Horda{/link}, el mundo supo lo que había costado su orgullo. {link:medivh}Medivh{/link} cayó en {link:karazhan}Karazhan{/link}, y el linaje de los Guardianes terminó con él. La propia Aegwynn se marchó al exilio, con su poder agotado. Entre los eruditos de {link:theramore-isle}Theramore{/link} se susurra que una anciana de gran sabiduría ha vivido un tiempo en las tierras salvajes de {link:kalimdor}Kalimdor{/link} y ha aconsejado a lady {link:jaina-proudmoore}Jaina Proudmoore{/link}. Pocos conocen su nombre, y quienes lo conocen se lo guardan.]=],
		},
		{
			title = "Sin registro",
			text = [=[Las historias no dicen cómo fue elegida Aegwynn por primera vez, ni cuántos años llevó el manto en total. Esta entrada recoge solo lo que es seguro.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "su hijo" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "a quien se dice que aconsejó" },
	},
})

Translate("esES", "llane-wrynn", {
	title = "Llane Wrynn",
	subtitle = "Rey de Ventormenta en la Primera Guerra",
	allegiance = "Reino de Ventormenta · Casa Wrynn",
	aliases = { "Llane", "Rey Llane" },
	sections = {
		{
			title = "Resumen",
			text = [=[Llane Wrynn era rey de {link:stormwind-city}Ventormenta{/link} cuando la {link:horde}Horda{/link} llegó a través del {link:dark-portal}Portal Oscuro{/link}. Fue un gobernante orgulloso y valiente, amigo de la infancia de {link:medivh}Medivh{/link} y de {link:anduin-lothar}Anduin Lothar{/link}, y padre del rey {link:varian-wrynn}Varian Wrynn{/link}. Guio a su pueblo a través de la larga agonía de la {link:first-war}Primera Guerra{/link} y murió dentro de su propio castillo cuando su ciudad caía.]=],
		},
		{
			title = "Importancia",
			text = [=[Llane fue el último rey de la antigua {link:stormwind-city}Ventormenta{/link}. Su muerte marcó el final de un reino que había permanecido solo y orgulloso durante generaciones. De su ruina nació la {link:alliance}Alianza{/link}, pues los supervivientes que dejó atrás llevaron el aviso de los orcos al norte, a {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Juventud",
			text = [=[Llane creció en compañía de dos muchachos extraordinarios: {link:anduin-lothar}Anduin Lothar{/link}, heredero de un antiguo linaje, y {link:medivh}Medivh{/link}, hijo del conjurador de la corte. Los tres eran inseparables. Cuando Medivh cayó en su largo sueño, Llane se hizo hombre sin él, y se alegró cuando su amigo despertó. Esa amistad lo cegaría en los años venideros.]=],
		},
		{
			title = "La Primera Guerra",
			text = [=[Cuando se vieron criaturas extrañas en la Cié{link:naga}naga{/link} Negra, Llane envió a {link:anduin-lothar}Lothar{/link} a averiguar qué eran. Eran orcos, y solo eran los primeros. Llane nombró a Lothar su campeón y envió mensajeros a los demás reinos humanos, pero pocos creyeron la historia. Durante años {link:stormwind-city}Ventormenta{/link} luchó sola. Las aldeas ardieron por todo el {link:elwynn-forest}Bosque de Elwynn{/link}, {link:westfall}Páramos de Poniente{/link} y {link:redridge-mountains}Crestagrana{/link}. La {link:horde}Horda{/link} sitió la capital y fue rechazada, pues Lothar atacó su retaguardia por sorpresa. Cuando {link:khadgar}Khadgar{/link} y la semiorca {link:garona}Garona{/link} advirtieron al rey de que el propio {link:medivh}Medivh{/link} había traído a los invasores, Llane no quiso creer que su amigo pudiera traicionarlo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Nombró a {link:anduin-lothar}Anduin Lothar{/link} campeón del reino y le confió su defensa.
• Envió avisos sobre los orcos a los demás reinos humanos.
• Defendió {link:stormwind-city}Ventormenta{/link} durante el primer gran asedio de la {link:horde}Horda{/link}.
• Tomó a {link:garona}Garona{/link} como confidente tras la caída de {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Tras la muerte de {link:medivh}Medivh{/link}, el {link:orcs}orco{/link} {link:orgrim-doomhammer}Orgrim Doomhammer{/link} se hizo con el mando de la {link:horde}Horda{/link} y la condujo de nuevo contra {link:stormwind-city}Ventormenta{/link}. Las murallas cedieron, pero Llane resistió en el castillo. {link:garona}Garona{/link}, que se había convertido en su consejera de confianza, seguía atada a la voluntad de los brujos de la Horda. Mató al rey en su cámara. El joven príncipe {link:varian-wrynn}Varian{/link} vio morir a su padre. Ventormenta cayó, y la Horda la arrasó. {link:anduin-lothar}Lothar{/link} reunió a los supervivientes y los llevó a través del mar hasta {link:lordaeron}Lordaeron{/link}. El reino de Llane ha sido reconstruido desde entonces, y su hijo reinó en su trono hasta su reciente desaparición. Su nieto, {link:anduin-wrynn}Anduin Wrynn{/link}, espera ahora en el castillo reconstruido, y lleva el nombre del campeón que salvó a su familia.]=],
		},
		{
			title = "Sin registro",
			text = [=[Las crónicas dicen poco de la reina de Llane o de los años de su reinado antes de que se abriera el Portal.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "su amigo de la infancia" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "su campeón" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "su hijo" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "dirigió a la Horda que tomó su ciudad" },
		{ id = "garona", name = "Garona", note = "su consejera, y su asesina" },
	},
})

Translate("esES", "anduin-lothar", {
	title = "Anduin Lothar",
	subtitle = "El León de Azeroth",
	allegiance = "Reino de Ventormenta · Alianza de Lordaeron",
	aliases = { "Lothar", "Sir Anduin Lothar" },
	sections = {
		{
			title = "Resumen",
			text = [=[Sir Anduin Lothar fue el campeón de {link:stormwind-city}Ventormenta{/link} en la {link:first-war}Primera Guerra{/link} y el primer comandante supremo de la {link:alliance}Alianza{/link} en la {link:second-war}Segunda Guerra{/link}. Era el último heredero conocido de la sangre real de {link:arathor}Arathor{/link}, el antiguo imperio del que surgieron los reinos humanos. Los soldados lo llamaban el León de {link:azeroth}Azeroth{/link}. Sin él, las naciones {link:humans}humanas{/link} quizá nunca se habrían unido.]=],
		},
		{
			title = "Importancia",
			text = [=[Lothar salvó {link:stormwind-city}Ventormenta{/link} dos veces: una al sacar a su pueblo de entre las cenizas, y otra al convencer a los reyes del norte de que lucharan por ella. La {link:alliance}Alianza{/link} que forjó aún perdura, y el nieto de su rey lleva su nombre.]=],
		},
		{
			title = "La Primera Guerra",
			text = [=[Lothar era amigo de la infancia de {link:llane-wrynn}Llane Wrynn{/link} y de {link:medivh}Medivh{/link}. Cuando se vieron los primeros orcos en la Cié{link:naga}naga{/link} Negra, el rey lo envió a explorar, y volvió con la noticia de una guerra. Llane lo nombró campeón del reino. Lothar luchó por todo el reino durante años. Cuando la {link:horde}Horda{/link} sitió {link:stormwind-city}Ventormenta{/link} por primera vez, condujo a los caballeros del reino rodeándola por mar y atacó su retaguardia, rompiendo el asalto. Con el joven mago {link:khadgar}Khadgar{/link}, subió a {link:karazhan}Karazhan{/link} y se enfrentó a Medivh, su amigo más antiguo, y allí el Guardián murió. Sin embargo, el reino no pudo salvarse. Cuando Ventormenta cayó, Lothar llevó a los supervivientes al norte, a través del mar.]=],
		},
		{
			title = "La Segunda Guerra",
			text = [=[En {link:lordaeron}Lordaeron{/link}, Lothar se presentó ante el rey {link:terenas-menethil}Terenas Menethil{/link} y los señores de las naciones del norte y les advirtió de que la {link:horde}Horda{/link} iría a por ellos después. Le escucharon. Nació la {link:alliance}Alianza de Lordaeron{/link}, y Lothar fue nombrado su comandante. Los altos elfos de {link:quel-thalas}Quel'Thalas{/link} se unieron a ella, pues tenían una antigua deuda con la sangre de {link:arathor}Arathor{/link}, y Lothar era su último heredero. Con {link:khadgar}Khadgar{/link} y el joven paladín {link:turalyon}Turalyon{/link} como lugartenientes, combatió a la Horda por los reinos del norte y la hizo retroceder hacia el sur.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Exploró a los primeros orcos en la Cié{link:naga}naga{/link} Negra y advirtió a su rey.
• Rompió el primer asedio de {link:stormwind-city}Ventormenta{/link} con una carga desde el mar.
• Mató a {link:medivh}Medivh{/link} en {link:karazhan}Karazhan{/link}, con {link:khadgar}Khadgar{/link} a su lado.
• Condujo al pueblo de Ventormenta al exilio en {link:lordaeron}Lordaeron{/link}.
• Convenció a los reinos humanos de que se unieran, y dirigió sus ejércitos.]=],
		},
		{
			title = "Destino",
			text = [=[Al final de la {link:second-war}Segunda Guerra{/link}, Lothar persiguió a la {link:horde}Horda{/link} hasta la {link:blackrock-mountain}Montaña Roca Negra{/link}, en {link:burning-steppes}Las Estepas Ardientes{/link}. Allí, en la batalla al pie de la montaña, cayó a manos de {link:orgrim-doomhammer}Orgrim Doomhammer{/link}. Su muerte no quebró la {link:alliance}Alianza{/link}. {link:turalyon}Turalyon{/link} tomó su espada, reagrupó a los soldados afligidos y aplastó a la Horda. {link:stormwind-city}Ventormenta{/link} fue recuperada, y el rey {link:varian-wrynn}Varian Wrynn{/link} puso más tarde a su hijo el nombre de Anduin en honor del campeón.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "su rey y amigo" },
		{ id = "medivh", name = "Medivh", note = "amigo, y enemigo" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "le dio el mando de la Alianza" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "su verdugo" },
		{ id = "turalyon", name = "Turalyon", note = "su lugarteniente y sucesor" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "lleva su nombre en su honor" },
	},
})

Translate("esES", "tiffin-wrynn", {
	title = "Tiffin Wrynn",
	subtitle = "Reina de Ventormenta",
	allegiance = "Reino de Ventormenta · Casa Wrynn",
	aliases = { "Tiffin", "Reina Tiffin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Tiffin Wrynn fue la reina del rey {link:varian-wrynn}Varian Wrynn{/link} y la madre del príncipe {link:anduin-wrynn}Anduin Wrynn{/link}. Estuvo junto a Varian en los años posteriores a la {link:second-war}Segunda Guerra{/link}, cuando {link:stormwind-city}Ventormenta{/link} resurgía de sus cenizas. No vivió para ver la ciudad terminada. Murió en el motín de los canteros, víctima de la disputa entre los nobles de la corona y los hombres que habían reconstruido sus murallas.]=],
		},
		{
			title = "Importancia",
			text = [=[La muerte de Tiffin es una de las heridas silenciosas de la nueva {link:stormwind-city}Ventormenta{/link}. Arrebató una madre al heredero del reino y una esposa a su rey. También marcó el momento en que la ira de los canteros se convirtió en revuelta abierta, de la que nació la {link:defias-brotherhood}Hermandad Defias{/link}.]=],
		},
		{
			title = "La reconstrucción",
			text = [=[Tras la {link:second-war}Segunda Guerra{/link}, los exiliados de {link:stormwind-city}Ventormenta{/link} volvieron a casa y encontraron su ciudad en ruinas. El {link:stonemasons-guild}Gremio de Canteros{/link}, dirigido por {link:edwin-vancleef}Edwin VanCleef{/link}, trabajó durante años para levantarla de nuevo. {link:varian-wrynn}Varian{/link}, el hijo de {link:llane-wrynn}Llane Wrynn{/link}, ocupó el trono de sus padres. Tiffin se convirtió en su reina, y con el tiempo le dio un hijo, Anduin, que recibió el nombre del campeón {link:anduin-lothar}Anduin Lothar{/link}. Durante un tiempo pareció que el reino podría conocer de nuevo la paz.]=],
		},
		{
			title = "El motín",
			text = [=[La {link:house-of-nobles}Cámara de los Nobles{/link} había prometido pagar a los canteros por su trabajo. Cuando el trabajo estuvo hecho, los nobles se negaron. Los canteros protestaron en las calles de la capital, y la protesta se convirtió en motín. En el caos, la reina fue abatida y murió. Los canteros fueron expulsados de la ciudad con deshonra, y los más resentidos huyeron a {link:westfall}Páramos de Poniente{/link}. Allí adoptaron el pañuelo rojo, y desde entonces su hermandad ha hecho presa en el reino.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue reina de {link:stormwind-city}Ventormenta{/link} en los años posteriores a su reconstrucción.
• Dio a {link:varian-wrynn}Varian{/link} un hijo y heredero, Anduin.]=],
		},
		{
			title = "Destino",
			text = [=[Tiffin yace muerta. Su hijo es todavía un niño, y en estos días espera en el {link:stormwind-keep}Castillo de Ventormenta{/link} mientras el destino de su padre sigue siendo desconocido y el alto señor {link:bolvar-fordragon}Bolvar Fordragon{/link} gobierna como regente. Los canteros que en otro tiempo sirvieron a la corona libran ahora su propia guerra contra ella desde las minas y las granjas de {link:westfall}Páramos de Poniente{/link}. Muchos en {link:stormwind-city}Ventormenta{/link} todavía hablan de la reina con cariño, y de su muerte con vergüenza.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Tiffin antes de ser reina. Las crónicas recogen su matrimonio, su hijo y su muerte, y casi nada de sus propias palabras o hechos. Esta entrada no llena ese silencio con conjeturas.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "su esposo" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "su hijo" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "el padre de su esposo" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "dirigió a los canteros cuyo motín le costó la vida" },
	},
})

Translate("esES", "terenas-menethil", {
	title = "Terenas Menethil",
	subtitle = "Rey de Lordaeron",
	allegiance = "Reino de Lordaeron · Alianza de Lordaeron",
	aliases = { "Terenas", "Rey Terenas" },
	sections = {
		{
			title = "Resumen",
			text = [=[El rey Terenas Menethil II gobernó {link:lordaeron}Lordaeron{/link}, el mayor de los reinos {link:humans}humanos{/link} del norte. Fue en su capital donde se fundó la {link:alliance}Alianza{/link}, y bajo su estandarte fue derrotada la {link:horde}Horda{/link} en la {link:second-war}Segunda Guerra{/link}. Fue el padre del príncipe {link:arthas-menethil}Arthas Menethil{/link} y de la princesa Calia. Murió a manos de su hijo, y su reino murió con él.]=],
		},
		{
			title = "Importancia",
			text = [=[Terenas fue la piedra angular de la {link:alliance}Alianza de Lordaeron{/link}. Acogió a los refugiados de {link:stormwind-city}Ventormenta{/link} y escuchó a {link:anduin-lothar}Anduin Lothar{/link} cuando otros reyes no quisieron hacerlo. Sin embargo, la paz que siguió a su victoria se deshilachó bajo su gobierno, y el destino final de su reino es el más oscuro de la historia de la humanidad.]=],
		},
		{
			title = "La Alianza",
			text = [=[Cuando {link:anduin-lothar}Lothar{/link} llevó al norte a los exiliados de {link:stormwind-city}Ventormenta{/link}, Terenas convocó en su capital a los señores de las naciones humanas. {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiras{/link}, {link:stromgarde-keep}Stromgarde{/link}, {link:alterac-mountains}Alterac{/link} y {link:city-of-dalaran}Dalaran{/link} enviaron a sus gobernantes y enviados, y más tarde se les unieron los altos elfos de {link:quel-thalas}Quel'Thalas{/link}. Terenas dio a Lothar el mando de los ejércitos combinados. Las propias tierras de {link:lordaeron}Lordaeron{/link} sufrieron mucho en la guerra, pero al final la {link:horde}Horda{/link} fue quebrada, y sus orcos fueron hechos prisioneros.]=],
		},
		{
			title = "La paz deshilachada",
			text = [=[Tras la guerra, Terenas ordenó que los orcos capturados fueran recluidos en grandes campos de internamiento. Los campos eran costosos, y gravó con impuestos a las demás naciones para pagarlos. Crecieron las disputas por los campos y por el destino del traidor reino de {link:alterac-mountains}Alterac{/link}. Uno a uno, {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} y {link:quel-thalas}Quel'Thalas{/link} abandonaron la {link:alliance}Alianza{/link}. Cuando una extraña plaga empezó a extenderse por las tierras de cultivo del norte de {link:lordaeron}Lordaeron{/link}, el rey envió a su hijo {link:arthas-menethil}Arthas{/link} y al paladín {link:uther-the-lightbringer}Uther el Iluminado{/link} a ponerle fin.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Acogió en su reino a los refugiados de {link:stormwind-city}Ventormenta{/link}.
• Fundó la {link:alliance}Alianza de Lordaeron{/link} y dio su mando a {link:anduin-lothar}Anduin Lothar{/link}.
• Ordenó construir los campos de internamiento tras la {link:second-war}Segunda Guerra{/link}.
• Envió a {link:arthas-menethil}Arthas{/link} y a {link:uther-the-lightbringer}Uther{/link} contra la plaga del norte.]=],
		},
		{
			title = "Destino",
			text = [=[{link:arthas-menethil}Arthas{/link} volvió a casa desde {red:northrend}Rasganorte{/red} como un héroe, y la gente de la capital esparció pétalos de flores a su paso. El príncipe entró en el salón del trono, se arrodilló ante su padre y luego lo mató con la espada rúnica {red:frostmourne}Agonía de Escarcha{/red}. Con la muerte del rey, el reino cayó ante la {link:scourge}Plaga{/link}. {link:uther-the-lightbringer}Uther{/link} llevó después las cenizas del rey en una urna hacia {link:quel-thalas}Quel'Thalas{/link}, pero Arthas abatió al paladín y esparció las cenizas. La capital de Terenas yace en ruinas, y bajo ella los {link:forsaken}Renegados{/link} de lady {link:sylvanas-windrunner}Sylvanas Windrunner{/link} han construido {link:undercity}Entrañas{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "su hijo, y su asesino" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "comandante de su Alianza" },
		{ id = "uther-the-lightbringer", name = "Uther el Iluminado", note = "su leal paladín" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "arzobispo de su fe" },
	},
})

Translate("esES", "arthas-menethil", {
	title = "Arthas Menethil",
	subtitle = "El príncipe caído",
	allegiance = [=[Plaga (antes Reino de Lordaeron, Caballeros de la Mano de Plata)]=],
	aliases = { "Arthas", "Príncipe Arthas" },
	sections = {
		{
			title = "Resumen",
			text = [=[Arthas Menethil fue el príncipe heredero de {link:lordaeron}Lordaeron{/link}, caballero de la Mano de Plata y alumno de {link:uther-the-lightbringer}Uther el Iluminado{/link}. Era valiente, amado y orgulloso. Partió para salvar a su pueblo de una plaga de no-muerte, y acabó destruyéndolo. Asesinó a su padre, el rey {link:terenas-menethil}Terenas Menethil{/link}, y condujo a la {link:scourge}Plaga{/link} por todo el norte. Ahora gobierna a los no-muertos desde el corazón helado de {red:northrend}Rasganorte{/red}.]=],
		},
		{
			title = "Importancia",
			text = [=[Ninguna caída en la historia de la humanidad ha sido tan grande ni tan terrible. El nombre de Arthas es maldito en cada tierra que conoció la {link:alliance}Alianza{/link}, y las tierras que asoló todavía se llaman las Tierras de la Peste.]=],
		},
		{
			title = "El príncipe",
			text = [=[Arthas era el único hijo de {link:terenas-menethil}Terenas{/link}. {link:uther-the-lightbringer}Uther{/link} lo instruyó como paladín de la {link:holy-light}Luz Sagrada{/link}, y fue acogido en la orden de la Mano de Plata. Cuando una plaga azotó las tierras de cultivo del norte de {link:lordaeron}Lordaeron{/link}, el rey envió a Arthas y a Uther a acabar con ella. Con {link:jaina-proudmoore}Jaina Proudmoore{/link} de {link:city-of-dalaran}Dalaran{/link} a su lado, Arthas siguió la enfermedad hasta el nigromante {link:kel-thuzad}Kel'Thuzad{/link} y su {link:cult-of-the-damned}Culto de los Malditos{/link}, y lo mató. Aun así, la plaga siguió extendiéndose. En Stratholme, Arthas descubrió que el grano de la ciudad estaba contaminado, y que todos los que lo habían comido se alzarían como no-muertos. Ordenó purgar la ciudad. Uther y Jaina se negaron a participar, y Arthas llevó a cabo la {link:culling-of-stratholme}Matanza de Stratholme{/link} sin ellos.]=],
		},
		{
			title = "La caída",
			text = [=[Arthas persiguió al señor del terror Mal'Ganis hasta Rasganorte. Allí quemó sus propios barcos para que sus hombres no pudieran dar la vuelta, y tomó la maldita espada rúnica {red:frostmourne}Agonía de Escarcha{/red}. Con ella mató a Mal'Ganis, pero la espada se apoderó de su alma. Volvió a {link:lordaeron}Lordaeron{/link} como siervo del {red:lich-king}Rey Exánime{/red}. En el salón del trono asesinó a su padre, y el reino cayó. Destruyó la orden de la Mano de Plata, mató a {link:uther-the-lightbringer}Uther{/link} y alzó de nuevo a {link:kel-thuzad}Kel'Thuzad{/link} junto a la Fuente del Sol tras arrasar {link:quel-thalas}Quel'Thalas{/link}. Mató a la general forestal {link:sylvanas-windrunner}Sylvanas Windrunner{/link} y ató su espíritu a su voluntad.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Llevó a cabo la {link:culling-of-stratholme}Matanza de Stratholme{/link}.
• Asesinó al rey {link:terenas-menethil}Terenas{/link} y entregó {link:lordaeron}Lordaeron{/link} a la {link:scourge}Plaga{/link}.
• Mató a {link:uther-the-lightbringer}Uther el Iluminado{/link}.
• Asoló {link:quel-thalas}Quel'Thalas{/link} y profanó la Fuente del Sol para alzar a {link:kel-thuzad}Kel'Thuzad{/link} como liche.
• Abrió el camino de la {link:burning-legion}Legión Ardiente{/link} hasta {link:city-of-dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Tras la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, el poder del Rey Exánime menguó, y Arthas perdió su dominio sobre {link:lordaeron}Lordaeron{/link}. {link:sylvanas-windrunner}Sylvanas{/link} se liberó de su control, y los {link:forsaken}Renegados{/link} se alzaron contra él. Convocado por su amo, Arthas regresó a Rasganorte. En el glaciar de Corona de Hielo luchó contra {link:illidan-stormrage}Illidan Stormrage{/link} y lo derrotó. Después subió al Trono Helado y se puso el yelmo del Rey Exánime, y los dos se convirtieron en uno. Arthas reina ahora como el Rey Exánime en Rasganorte. En Lordaeron, {link:kel-thuzad}Kel'Thuzad{/link} dirige la {link:scourge}Plaga{/link} en su nombre. {link:muradin-bronzebeard}Muradin Bronzebeard{/link}, que una vez lo siguió al norte, nunca volvió a casa.]=],
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "su padre, y su víctima" },
		{ id = "uther-the-lightbringer", name = "Uther el Iluminado", note = "su maestro, y su víctima" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "su amor perdido" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "enemigo, y después siervo" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "el Rey Exánime al que se unió" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "enemigo en Corona de Hielo" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "su víctima y enemiga" },
	},
})

Translate("esES", "uther-the-lightbringer", {
	title = "Uther el Iluminado",
	subtitle = "El primero de los paladines",
	allegiance = "Caballeros de la Mano de Plata · Iglesia de la Luz Sagrada",
	aliases = { "Uther", "Lord Uther" },
	sections = {
		{
			title = "Resumen",
			text = [=[Uther el Iluminado fue el primer paladín de la {link:holy-light}Luz Sagrada{/link} y el líder de los Caballeros de la Mano de Plata. Aprendió su fe al lado del arzobispo {link:alonsus-faol}Alonsus Faol{/link}, combatió a la {link:horde}Horda{/link} por todo el norte en la {link:second-war}Segunda Guerra{/link} e instruyó al príncipe {link:arthas-menethil}Arthas Menethil{/link}. Fue maestro y amigo del príncipe, y murió a manos del príncipe.]=],
		},
		{
			title = "Importancia",
			text = [=[Uther mostró a los reinos humanos que la fe y el acero podían ir juntos. La orden que dirigió defendió {link:lordaeron}Lordaeron{/link} durante una generación, y su nombre aún lo pronuncia con reverencia todo paladín del mundo.]=],
		},
		{
			title = "La Mano de Plata",
			text = [=[Tras la {link:first-war}Primera Guerra{/link}, llegó al norte la noticia de que la {link:horde}Horda{/link} había masacrado a los clérigos de la {link:northshire-abbey}Abadía de Villanorte{/link}. {link:alonsus-faol}Alonsus Faol{/link} decidió que los servidores de la Luz ya no quedarían indefensos. Con la bendición de {link:anduin-lothar}Anduin Lothar{/link}, reunió a guerreros de fe firme y les enseñó a esgrimir el poder sagrado en la batalla. Uther fue el primero de ellos. Cuando terminó su instrucción, el arzobispo lo nombró líder de los nuevos Caballeros de la Mano de Plata. Uther y sus paladines, entre ellos {link:turalyon}Turalyon{/link} y {link:tirion-fordring}Tirion Fordring{/link}, lucharon durante toda la {link:second-war}Segunda Guerra{/link} y llevaron curación y esperanza allí donde la lucha era más dura.]=],
		},
		{
			title = "El príncipe",
			text = [=[En los años de paz, Uther tomó como alumno al joven {link:arthas-menethil}Arthas{/link} y lo acogió en la orden. Cuando estalló una plaga en el norte de {link:lordaeron}Lordaeron{/link}, el rey {link:terenas-menethil}Terenas Menethil{/link} los envió a ambos a ponerle fin. En Stratholme, Arthas ordenó que el pueblo de la ciudad fuera ejecutado antes de que la plaga pudiera alzarlo. Uther se negó. No quiso abatir a los vivos, y Arthas lo apartó de su servicio. La {link:culling-of-stratholme}Matanza de Stratholme{/link} siguió adelante sin él.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue el primer paladín ordenado por {link:alonsus-faol}Alonsus Faol{/link} y dirigió a los Caballeros de la Mano de Plata.
• Combatió a la {link:horde}Horda{/link} en la {link:second-war}Segunda Guerra{/link}.
• Instruyó al príncipe {link:arthas-menethil}Arthas{/link} en los caminos de la Luz.
• Se negó a participar en la {link:culling-of-stratholme}Matanza de Stratholme{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Cuando {link:arthas-menethil}Arthas{/link} regresó de {red:northrend}Rasganorte{/red} y asesinó a su padre, el príncipe se volvió contra la orden que lo había criado. Quebró la Mano de Plata y dio caza a sus caballeros. Uther y sus últimos paladines custodiaban la urna que contenía las cenizas del rey {link:terenas-menethil}Terenas{/link}. Arthas fue a por ella, y el alumno mató a su maestro con la espada rúnica {red:frostmourne}Agonía de Escarcha{/red}. Una tumba se alza ahora en memoria de Uther en las {link:western-plaguelands}Tierras de la Peste del Oeste{/link}, un lugar de duelo en una tierra muerta. Algunos de los paladines que instruyó aún viven, y lo recuerdan.]=],
		},
	},
	bonds = {
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "su mentor" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "su alumno, y su verdugo" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "su rey" },
		{ id = "turalyon", name = "Turalyon", note = "un hermano de la Mano de Plata" },
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "un hermano de la Mano de Plata" },
	},
})

Translate("esES", "alonsus-faol", {
	title = "Alonsus Faol",
	subtitle = "Arzobispo de la Luz Sagrada",
	allegiance = "Iglesia de la Luz Sagrada · Caballeros de la Mano de Plata",
	aliases = { "Arzobispo Faol", "Arzobispo Alonsus Faol" },
	sections = {
		{
			title = "Resumen",
			text = [=[Alonsus Faol fue el arzobispo de la Iglesia de la {link:holy-light}Luz Sagrada{/link}, el padre espiritual de los reinos humanos en la época de la {link:second-war}Segunda Guerra{/link}. Era un anciano bajo y robusto, de barba blanca y rostro bondadoso, querido por plebeyos y reyes por igual. Fundó los Caballeros de la Mano de Plata y ordenó a {link:uther-the-lightbringer}Uther el Iluminado{/link} como el primero de los paladines.]=],
		},
		{
			title = "Importancia",
			text = [=[Antes de Faol, los servidores de la Luz curaban y rezaban mientras otros luchaban. Después de él, cabalgaron a la guerra. Las órdenes de paladines de todas las tierras humanas, y los jóvenes paladines que hoy se instruyen en la {link:northshire-abbey}Abadía de Villanorte{/link}, siguen todos el camino que él abrió.]=],
		},
		{
			title = "La Mano de Plata",
			text = [=[Faol había servido a la fe durante mucho tiempo, y tomó al joven {link:uther-the-lightbringer}Uther{/link} como aprendiz muchos años antes de que llegaran los orcos. Durante la {link:first-war}Primera Guerra{/link}, la {link:horde}Horda{/link} quemó la abadía de {link:northshire-abbey}Villanorte{/link} y masacró a sus clérigos. Cuando los supervivientes de {link:stormwind-city}Ventormenta{/link} llegaron a {link:lordaeron}Lordaeron{/link}, el arzobispo supo de la masacre, y decidió que no volvería a ocurrir. Junto con {link:anduin-lothar}Anduin Lothar{/link}, fundó una orden de guerreros sagrados. Eligió caballeros de fe firme y les enseñó a invocar la Luz en la batalla. Uther, {link:turalyon}Turalyon{/link}, {link:tirion-fordring}Tirion Fordring{/link} y unos pocos más fueron los primeros. Cuando completaron su instrucción, Faol nombró a Uther líder de los Caballeros de la Mano de Plata.]=],
		},
		{
			title = "La paz",
			text = [=[Faol estuvo presente cuando los señores de las naciones humanas se reunieron en la capital de {link:lordaeron}Lordaeron{/link}. Se dice que ayudó a calmar los ánimos cuando sus disputas se encendían. Tras la guerra dedicó sus cuidados a la reconstrucción del sur. Envió a sus sacerdotes y paladines allí donde se les necesitaba, y apoyó la construcción de la nueva {link:cathedral-of-light}Catedral de la Luz{/link} en {link:stormwind-city}Ventormenta{/link} y la restauración de {link:northshire-abbey}Villanorte{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Instruyó a {link:uther-the-lightbringer}Uther{/link} en la fe de la Luz.
• Fundó los Caballeros de la Mano de Plata con {link:anduin-lothar}Anduin Lothar{/link}.
• Ordenó a los primeros paladines y nombró a Uther su líder.
• Aconsejó a los señores de la {link:alliance}Alianza{/link} durante la {link:second-war}Segunda Guerra{/link}.
• Ayudó a reconstruir {link:stormwind-city}Ventormenta{/link} y la {link:northshire-abbey}Abadía de Villanorte{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Faol murió en los años posteriores a la {link:second-war}Segunda Guerra{/link}. Las crónicas no dicen cómo. Su discípulo {link:archbishop-benedictus}Benedictus{/link} le sucedió como arzobispo, y aún guarda la {link:cathedral-of-light}Catedral de la Luz{/link} en {link:stormwind-city}Ventormenta{/link}. Faol fue sepultado en los {link:tirisfal-glades}Claros de Tirisfal{/link}, en una tumba llamada Tumba de Faol. Esa tierra pertenece ahora a los no-muertos, y los {link:forsaken}Renegados{/link} caminan por donde antes acudían a rezar los fieles.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica cuenta cómo murió Alonsus Faol, ni cuándo. Tampoco recoge mucho de su vida antes de que fuera arzobispo.]=],
		},
	},
	bonds = {
		{ id = "uther-the-lightbringer", name = "Uther el Iluminado", note = "su aprendiz" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "fundó con él la Mano de Plata" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "su rey en Lordaeron" },
	},
})

Translate("esES", "orgrim-doomhammer", {
	title = "Orgrim Doomhammer",
	subtitle = "Jefe de Guerra de la Horda en la Segunda Guerra",
	allegiance = "Horda · clan Roca Negra",
	aliases = { "Orgrim", "Jefe de Guerra Doomhammer" },
	sections = {
		{
			title = "Resumen",
			text = [=[Orgrim Doomhammer fue el Jefe de Guerra de la {link:horde}Horda{/link} que conquistó {link:stormwind-city}Ventormenta{/link} y dirigió a los orcos en la {link:second-war}Segunda Guerra{/link}. Era un guerrero del {link:blackrock-clan}clan Roca Negra{/link}, portador del gran martillo de su familia y el amigo más antiguo de Durotan de los {link:frostwolf-clan}Lobo Gélido{/link}. Odiaba a los brujos que habían corrompido a su pueblo, e intentó, a su manera, liberarlo. Al final de su vida encontró al {link:orcs}orco{/link} que terminaría esa obra: {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Doomhammer hizo de la {link:horde}Horda{/link} un único ejército con una única voluntad. Bajo su mando estuvo más cerca que nunca de conquistar los reinos humanos. Sin embargo, su mayor legado no es una conquista. Es la nueva Horda, y su capital, {link:orgrimmar}Orgrimmar{/link}, lleva su nombre.]=],
		},
		{
			title = "La Primera Guerra",
			text = [=[En los primeros años de la guerra, Orgrim sirvió como segundo del Jefe de Guerra Blackhand, un títere del brujo {link:gul-dan}Gul'dan{/link}. Cuando Durotan fue asesinado por los sicarios de Gul'dan, la ira de Orgrim ya no pudo contenerse. Tras la muerte de {link:medivh}Medivh{/link}, desafió a Blackhand a un duelo a muerte y le aplastó el cráneo con el Martillo Maldito. Como Jefe de Guerra, prohibió la magia oscura que había envenenado Draenor. Condujo de nuevo a la {link:horde}Horda{/link} contra {link:stormwind-city}Ventormenta{/link}, y esta vez la ciudad cayó. Después encontró la guarida del {link:shadow-council}Consejo de la Sombra{/link} de los brujos y masacró a la mayoría de sus miembros.]=],
		},
		{
			title = "La Segunda Guerra",
			text = [=[Doomhammer perdonó a {link:gul-dan}Gul'dan{/link}, que le prometió nuevas armas. Reunió toda la fuerza de la {link:horde}Horda{/link} y marchó hacia el norte. Tomó las {link:kingdom-of-ironforge}tierras de los enanos{/link} de Khaz Modan, se alió con los trols del bosque amani y usó en la batalla a los dragones rojos del {link:dragonmaw-clan}clan Faucedraco{/link}. Sus ejércitos quemaron los bosques de {link:quel-thalas}Quel'Thalas{/link} y sitiaron la capital de {link:lordaeron}Lordaeron{/link}. Entonces Gul'dan lo traicionó y se llevó a buena parte de la Horda. El asedio fracasó. En la {link:blackrock-mountain}Montaña Roca Negra{/link}, Doomhammer mató a {link:anduin-lothar}Anduin Lothar{/link} en combate, pero el paladín {link:turalyon}Turalyon{/link} reagrupó a la {link:alliance}Alianza{/link}, y la Horda fue aplastada.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Mató a Blackhand y se proclamó Jefe de Guerra.
• Conquistó {link:stormwind-city}Ventormenta{/link} y puso fin a la {link:first-war}Primera Guerra{/link}.
• Destruyó {link:shadow-council}el Consejo{/link} de la Sombra.
• Condujo a la {link:horde}Horda{/link} hasta las puertas de la capital de {link:lordaeron}Lordaeron{/link}.
• Mató a {link:anduin-lothar}Anduin Lothar{/link} en la {link:blackrock-mountain}Montaña Roca Negra{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Doomhammer fue hecho prisionero y exhibido encadenado en la capital de {link:lordaeron}Lordaeron{/link}. Escapó y vivió escondido durante muchos años. Cuando el joven {link:thrall}Thrall{/link}, hijo de Durotan, fue a buscarlo, el viejo Jefe de Guerra lo reconoció enseguida. Se unió a Thrall para liberar a los orcos de los campos de internamiento, y cayó en una de esas batallas en las colinas de {link:hillsbrad-foothills}Trabalomas{/link}. Antes de morir, nombró a Thrall nuevo Jefe de Guerra. Thrall lleva ahora la armadura negra de Doomhammer y empuña su martillo en {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "su heredero como Jefe de Guerra" },
		{ id = "gul-dan", name = "Gul'dan", note = "el brujo al que despreciaba" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "el enemigo al que mató" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "el rey cuya ciudad tomó" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "otro jefe de clan" },
	},
})

Translate("esES", "grom-hellscream", {
	title = "Grom Hellscream",
	subtitle = "Jefe del clan Grito de Guerra",
	allegiance = "Horda · clan Grito de Guerra",
	aliases = { "Grommash", "Grommash Hellscream" },
	sections = {
		{
			title = "Resumen",
			text = [=[Grom Hellscream fue el jefe del clan Grito de Guerra, el más feroz de los caudillos {link:orcs}orcos{/link} y el amigo más fiel de {link:thrall}Thrall{/link}. Fue el primer orco que bebió la sangre del demonio {link:mannoroth}Mannoroth{/link}, y así ató a su pueblo a la {link:burning-legion}Legión Ardiente{/link}. También fue el orco que rompió ese vínculo, a costa de su propia vida.]=],
		},
		{
			title = "Importancia",
			text = [=[La maldición de los orcos empezó con Grom y terminó con él. Su muerte en {link:ashenvale}Vallefresno{/link} liberó a los orcos de la sangre demoníaca, y la {link:horde}Horda{/link} de hoy debe su libertad a su última batalla.]=],
		},
		{
			title = "La maldición de sangre",
			text = [=[En {red:draenor}Draenor{/red}, el brujo {link:gul-dan}Gul'dan{/link} reunió a los jefes de los clanes y les ofreció un trago de la sangre de {link:mannoroth}Mannoroth{/link}. Grom fue el primero en beber, y los demás lo siguieron. La sangre llenó a los orcos de una furia terrible y los ató a la voluntad de la Legión. Cuando la {link:horde}Horda{/link} marchó sobre {link:azeroth}Azeroth{/link}, Gul'dan se las arregló para mantener a Grom y a su clan Grito de Guerra en Draenor. Se perdieron por completo la {link:second-war}Segunda Guerra{/link}. Tras la guerra, cruzaron el {link:dark-portal}Portal Oscuro{/link} y lucharon por él hasta que fue destruido, y quedaron varados en las tierras humanas.]=],
		},
		{
			title = "El letargo",
			text = [=[Durante muchos años, el clan Grito de Guerra vivió oculto en las tierras salvajes de {link:lordaeron}Lordaeron{/link}. Como todos los orcos, Grom estaba enfermo por la pérdida de la furia del demonio. Aun así, combatió el letargo con una voluntad de hierro. Cuando el joven {link:thrall}Thrall{/link} fue a buscarlo, Grom vio en él la esperanza de su pueblo. Se unió a Thrall para liberar a los orcos de los campos de internamiento. Fue capturado por los humanos en vísperas de la {link:third-war}Tercera Guerra{/link}, y Thrall lo liberó de nuevo.]=],
		},
		{
			title = "Kalimdor",
			text = [=[Los orcos navegaron hacia el oeste, hasta {link:kalimdor}Kalimdor{/link}. Allí el clan Grito de Guerra fue enviado a los bosques de {link:ashenvale}Vallefresno{/link} a talar madera, y chocó con los {link:night-elves}elfos de la noche{/link}. El semidiós {link:cenarius}Cenarius{/link} acudió a defender el bosque. Desesperados por vencer, Grom y sus guerreros bebieron de un manantial que {link:mannoroth}Mannoroth{/link} había contaminado con su sangre. La vieja maldición regresó. En esa furia, Grom mató a Cenarius. {link:thrall}Thrall{/link}, con la ayuda de {link:jaina-proudmoore}Jaina Proudmoore{/link}, capturó a su amigo y lo purificó de la furia.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue el primer {link:orcs}orco{/link} que bebió la sangre de {link:mannoroth}Mannoroth{/link}.
• Defendió el {link:dark-portal}Portal Oscuro{/link} contra la {link:alliance}Alianza{/link} tras la {link:second-war}Segunda Guerra{/link}.
• Resistió el letargo orco durante años de ocultación.
• Ayudó a {link:thrall}Thrall{/link} a liberar a los orcos de los campos.
• Mató a {link:cenarius}Cenarius{/link}, y después mató a Mannoroth.]=],
		},
		{
			title = "Destino",
			text = [=[Grom y {link:thrall}Thrall{/link} fueron juntos al cañón donde esperaba {link:mannoroth}Mannoroth{/link}. Thrall cayó ante el poder del demonio. Grom cargó solo, clavó su hacha en el pecho de Mannoroth y lo mató. La muerte del demonio liberó a los orcos de la maldición de sangre. Grom murió de sus heridas en brazos de Thrall. Su clan aún tala los árboles de {link:ashenvale}Vallefresno{/link} en nombre de la {link:horde}Horda{/link}, y los elfos de la noche aún luchan con ellos por cada árbol.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "su Jefe de Guerra y amigo" },
		{ id = "gul-dan", name = "Gul'dan", note = "le dio la sangre del demonio" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "otro jefe de clan" },
		{ id = "archimonde", name = "Archimonde", note = "el amo del demonio al que mató" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "ayudó a liberarlo" },
	},
})

Translate("esES", "gul-dan", {
	title = "Gul'dan",
	subtitle = "El traidor de los orcos",
	allegiance = "Consejo de la Sombra · clan Stormreaver",
	sections = {
		{
			title = "Resumen",
			text = [=[Gul'dan fue el primer brujo {link:orcs}orco{/link} y el artífice de la antigua {link:horde}Horda{/link}. En otro tiempo fue aprendiz del chamán {link:ner-zhul}Ner'zhul{/link}. Vendió a su pueblo a la {link:burning-legion}Legión Ardiente{/link} a cambio de poder, y envenenó a la vez a su raza y a su mundo. Abrió el {link:dark-portal}Portal Oscuro{/link} con {link:medivh}Medivh{/link} y dirigió a los amos ocultos de la Horda, {link:shadow-council}el Consejo{/link} de la Sombra. Al final, traicionó a la propia Horda.]=],
		},
		{
			title = "Importancia",
			text = [=[Gran parte del sufrimiento de los orcos, y de los pueblos contra los que lucharon, se remonta a la ambición de Gul'dan. Su {link:fel-magic}magia vil{/link} drenó la vida de {red:draenor}Draenor{/red}. Su sangre demoníaca convirtió a los orcos en esclavos de su furia. Su traición le costó a la {link:horde}Horda{/link} la {link:second-war}Segunda Guerra{/link}.]=],
		},
		{
			title = "El Consejo de la Sombra",
			text = [=[En Draenor, el señor demoníaco {link:kil-jaeden}Kil'jaeden{/link} buscaba un siervo entre los orcos. Cuando {link:ner-zhul}Ner'zhul{/link} empezó a dudar del demonio, Kil'jaeden recurrió a Gul'dan, que no tenía ninguna duda. Kil'jaeden le enseñó las artes de la hechicería vil. Gul'dan fundó {link:shadow-council}el Consejo{/link} de la Sombra, un círculo de brujos que gobernaba los clanes desde detrás de un Jefe de Guerra títere, Blackhand. Ofreció a los jefes la sangre de {link:mannoroth}Mannoroth{/link}, y bebieron. Entonces le llegó una voz de otro mundo. Era {link:medivh}Medivh{/link}, y juntos abrieron el {link:dark-portal}Portal Oscuro{/link} hacia {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Las guerras",
			text = [=[Al final de la {link:first-war}Primera Guerra{/link}, Gul'dan intentó arrebatar de la mente moribunda de {link:medivh}Medivh{/link} los secretos de la Tumba de {link:sargeras}Sargeras{/link}. El esfuerzo lo sumió en un largo estupor. Mientras dormía, {link:orgrim-doomhammer}Orgrim Doomhammer{/link} mató a Blackhand y destruyó a la mayor parte del {link:shadow-council}Consejo de la Sombra{/link}. Cuando Gul'dan despertó, compró su vida con la promesa de nuevas armas. Él y sus brujos alzaron a los primeros caballeros de la muerte de la {link:horde}Horda{/link}. Pero su lealtad era una máscara. Mientras Doomhammer sitiaba la capital de {link:lordaeron}Lordaeron{/link}, Gul'dan tomó a sus seguidores y zarpó en busca de la Tumba de Sargeras bajo el mar.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fundó {link:shadow-council}el Consejo{/link} de la Sombra y gobernó la {link:horde}Horda{/link} a través de Blackhand.
• Dio a los jefes la sangre de {link:mannoroth}Mannoroth{/link}.
• Abrió el {link:dark-portal}Portal Oscuro{/link} con {link:medivh}Medivh{/link}.
• Alzó a los primeros caballeros de la muerte de la Horda.
• Abandonó a Doomhammer a las puertas de la capital de {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Gul'dan alzó la Tumba de {link:sargeras}Sargeras{/link} desde las profundidades de Mare Magnum y entró en ella, con la esperanza de reclamar el poder de un dios. Los demonios que la guardaban lo despedazaron. Los guerreros de Doomhammer, enviados a castigar su traición, masacraron a sus seguidores. Sin ellos, la {link:horde}Horda{/link} no pudo mantener el asedio, y fue empujada a la derrota. El {link:skull-of-gul-dan}cráneo de Gul'dan{/link} le sobrevivió, y albergó un poder oscuro propio hasta que fue destruido en la {link:third-war}Tercera Guerra{/link}.]=],
		},
	},
	bonds = {
		{ id = "ner-zhul", name = "Ner'zhul", note = "su primer maestro" },
		{ id = "medivh", name = "Medivh", note = "abrió con él el Portal Oscuro" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "el Jefe de Guerra al que traicionó" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "el primero en beber su sangre" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "tomó el poder de su cráneo" },
	},
})

Translate("esES", "ner-zhul", {
	title = "Ner'zhul",
	subtitle = "Chamán anciano de los Shadowmoon",
	allegiance = "clan Shadowmoon · Plaga",
	sections = {
		{
			title = "Resumen",
			text = [=[Ner'zhul fue el chamán anciano del clan Shadowmoon y el guía espiritual más respetado de los orcos de {red:draenor}Draenor{/red}. El señor demoníaco {link:kil-jaeden}Kil'jaeden{/link} lo engañó y lo usó para volver a los orcos contra los draenei. Más tarde, Ner'zhul desgarró su propio mundo en un intento de huir de él. Capturado por los demonios, fue convertido en el {red:lich-king}Rey Exánime{/red}, amo de la {link:scourge}Plaga{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Ner'zhul trajo la ruina dos veces. Como chamán, abrió el corazón de su pueblo a la {link:burning-legion}Legión Ardiente{/link}. Como Rey Exánime, envió una plaga de no-muerte sobre {link:lordaeron}Lordaeron{/link}. La {link:third-war}Tercera Guerra{/link} y las tierras muertas del norte son obra suya tanto como de cualquier otro.]=],
		},
		{
			title = "El engañado",
			text = [=[En los viejos tiempos de Draenor, los orcos vivían en clanes de cazadores y chamanes. Ner'zhul hablaba por los espíritus entre ellos. Entonces {link:kil-jaeden}Kil'jaeden{/link} acudió a él, disfrazado de espíritu de los ancestros, y le susurró que los pacíficos draenei conspiraban contra los orcos. Ner'zhul le creyó y llevó a su pueblo a la guerra. Solo más tarde vio la verdad, y cuando se negó a ir más lejos, Kil'jaeden recurrió en su lugar a su aprendiz, {link:gul-dan}Gul'dan{/link}. Ner'zhul fue apartado y vivió avergonzado mientras la {link:horde}Horda{/link} marchaba sobre {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "La destrucción",
			text = [=[Tras la {link:second-war}Segunda Guerra{/link}, los orcos que se habían quedado en Draenor se reunieron en torno al viejo chamán. Reabrió el {link:dark-portal}Portal Oscuro{/link} y envió guerreros a robar poderosas reliquias de {link:azeroth}Azeroth{/link}, con la intención de abrir portales a nuevos mundos para su pueblo. La {link:alliance}Alianza{/link} envió una expedición a través del Portal para detenerlo. Ner'zhul abrió sus portales de todos modos. Las energías destrozaron Draenor, y huyó por una grieta con sus seguidores.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Guio a los orcos como su mayor chamán.
• Condujo a los clanes contra los draenei bajo el engaño de {link:kil-jaeden}Kil'jaeden{/link}.
• Reabrió el {link:dark-portal}Portal Oscuro{/link} tras la {link:second-war}Segunda Guerra{/link}.
• Destrozó Draenor con sus portales.
• Como Rey Exánime, alzó la {link:scourge}Plaga{/link} y desató la plaga sobre {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[{link:kil-jaeden}Kil'jaeden{/link} lo esperaba al otro lado de la grieta. El demonio arrancó la carne del cuerpo del chamán y ató su espíritu a una armadura y un yelmo. Encerró a Ner'zhul en un bloque de hielo y lo lanzó a {link:azeroth}Azeroth{/link}. Cayó en el glaciar de Corona de Hielo, en {red:northrend}Rasganorte{/red}, y allí se convirtió en el Rey Exánime. Desde el Trono Helado alzó la {link:scourge}Plaga{/link}. Llamó a {link:kel-thuzad}Kel'Thuzad{/link} a su servicio y envió la plaga al sur. Por fin reclamó al príncipe {link:arthas-menethil}Arthas Menethil{/link} a través de la espada rúnica {red:frostmourne}Agonía de Escarcha{/red}. Cuando su poder menguó, convocó a Arthas a Corona de Hielo, y el príncipe se puso su yelmo. Ner'zhul y Arthas son ahora uno, y el Rey Exánime gobierna en el norte.]=],
		},
	},
	bonds = {
		{ id = "gul-dan", name = "Gul'dan", note = "su aprendiz, y su usurpador" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "el príncipe al que reclamó y con el que se unió" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "su siervo" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "jefe de clan de su Horda" },
	},
})

Translate("esES", "archimonde", {
	title = "Archimonde",
	subtitle = "El Profanador",
	allegiance = "Legión Ardiente",
	sections = {
		{
			title = "Resumen",
			text = [=[Archimonde el Profanador fue uno de los grandes señores de la {link:burning-legion}Legión Ardiente{/link}, solo por debajo de su oscuro amo, {link:sargeras}Sargeras{/link}. En otro tiempo fue un líder de los eredar, un pueblo orgulloso de otro mundo, hasta que Sargeras les ofreció poder y él aceptó. Libró las guerras de la Legión en incontables mundos. En {link:azeroth}Azeroth{/link}, estuvo más cerca que ningún demonio antes que él de devorar el mundo, y murió al pie del Árbol del Mundo.]=],
		},
		{
			title = "Importancia",
			text = [=[La invasión de Archimonde en la {link:third-war}Tercera Guerra{/link} fue el mayor asalto demoníaco que el mundo había conocido desde la {link:war-of-the-ancients}Guerra de los Ancestros{/link}. Su derrota en el {link:mount-hyjal}Monte Hyjal{/link} forjó una paz incómoda entre {link:orcs}orcos{/link}, {link:humans}humanos{/link} y {link:night-elves}elfos de la noche{/link}, una paz que ha dado forma a {link:kalimdor}Kalimdor{/link} desde entonces.]=],
		},
		{
			title = "Los eredar",
			text = [=[Hace mucho tiempo, los eredar eran gobernados por tres líderes: Archimonde, {link:kil-jaeden}Kil'jaeden{/link} y Velen. {link:sargeras}Sargeras{/link} acudió a ellos con una oferta de conocimiento y poder. Archimonde y Kil'jaeden aceptaron, y fueron retorcidos hasta convertirse en demonios. Velen se negó y huyó con sus seguidores. Archimonde se convirtió en uno de los mayores lugartenientes de Sargeras. En la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, hace diez mil años, la Legión llegó a {link:azeroth}Azeroth{/link} a través del {link:well-of-eternity}Pozo de la Eternidad{/link}. Fue rechazada cuando el Pozo fue destruido.]=],
		},
		{
			title = "La Tercera Guerra",
			text = [=[La Legión regresó muchas eras después. Cuando la {link:scourge}Plaga{/link} hubo asolado {link:lordaeron}Lordaeron{/link}, el liche {link:kel-thuzad}Kel'Thuzad{/link} usó el libro de hechizos de {link:medivh}Medivh{/link} para invocar a Archimonde en la ciudad de {link:city-of-dalaran}Dalaran{/link}. El señor demoníaco destruyó la ciudad de los magos con un solo golpe de su poder. Después condujo a la Legión a {link:kalimdor}Kalimdor{/link}, donde las últimas aguas del {link:well-of-eternity}Pozo de la Eternidad{/link} yacían bajo el Árbol del Mundo, {link:nordrassil}Nordrassil{/link}. Pretendía drenar su poder y consumir el mundo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Aceptó la oferta de {link:sargeras}Sargeras{/link} y se convirtió en un señor de la Legión.
• Hizo la guerra a {link:azeroth}Azeroth{/link} en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.
• Fue invocado en {link:city-of-dalaran}Dalaran{/link} por {link:kel-thuzad}Kel'Thuzad{/link} y la destruyó.
• Marchó sobre el {link:mount-hyjal}Monte Hyjal{/link} para drenar el poder de {link:nordrassil}Nordrassil{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[En la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, los orcos de {link:thrall}Thrall{/link}, los hombres de {link:jaina-proudmoore}Jaina Proudmoore{/link} y los elfos de la noche de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} y {link:malfurion-stormrage}Malfurion Stormrage{/link} defendieron las laderas de la montaña tanto como pudieron. Archimonde subió por fin hasta el Árbol del Mundo. Malfurion hizo sonar el Cuerno de {link:cenarius}Cenarius{/link}, y una inmensa hueste de espíritus de los ancestros se abalanzó sobre el señor demoníaco y lo destruyó en una gran explosión. El poder de {link:nordrassil}Nordrassil{/link} se agotó, y los elfos de la noche perdieron su inmortalidad. Pero la invasión de la Legión quedó quebrada. Sus demonios aún permanecen en los bosques corruptos de {link:felwood}Frondavil{/link}, y su sombra no ha abandonado el mundo.]=],
		},
	},
	bonds = {
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "lo invocó en Azeroth" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "provocó su destrucción" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "enemigo en la Tercera Guerra" },
		{ id = "queen-azshara", name = "Reina Azshara", note = "la que abrió el camino a la antigua Legión" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "mató a su siervo Mannoroth" },
	},
})

Translate("esES", "illidan-stormrage", {
	title = "Illidan Stormrage",
	subtitle = "El Traidor",
	allegiance = "Desconocida (antes la resistencia kaldorei)",
	aliases = { "Illidan", "el Traidor" },
	sections = {
		{
			title = "Resumen",
			text = [=[Illidan Stormrage fue un hechicero {link:night-elves}elfo de la noche{/link} del mundo antiguo, hermano gemelo de {link:malfurion-stormrage}Malfurion Stormrage{/link} y rival por el amor de {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Luchó contra la {link:burning-legion}Legión Ardiente{/link}, y también la sirvió. Estuvo encarcelado durante diez mil años y fue liberado en la {link:third-war}Tercera Guerra{/link}. Algunos lo llaman héroe y muchos lo llaman traidor. Su propio pueblo lo llamó el Traidor.]=],
		},
		{
			title = "Importancia",
			text = [=[Las decisiones de Illidan han salvado y amenazado el mundo a partes iguales. En tiempos antiguos, llevó las aguas del {link:well-of-eternity}Pozo de la Eternidad{/link} al {link:mount-hyjal}Monte Hyjal{/link}, donde aún yacen bajo {link:nordrassil}Nordrassil{/link}. En la {link:third-war}Tercera Guerra{/link}, mató a un señor de la Legión y tomó su poder para sí.]=],
		},
		{
			title = "La Guerra de los Ancestros",
			text = [=[Illidan nació con ojos ambarinos, una marca que según se decía auguraba grandeza. Se sintió atraído por la {link:arcane-magic}magia arcana{/link} igual que su hermano por la senda de {link:cenarius}Cenarius{/link}. En la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, luchó junto a los elfos de la noche contra la {link:queen-azshara}reina Azshara{/link} y sus aliados demoníacos. Pero sintió celos de su hermano y hambre de poder, y al final acudió al propio {link:sargeras}Sargeras{/link}. El señor demoníaco le quemó los ojos y le dio una nueva visión. Cuando el {link:well-of-eternity}Pozo de la Eternidad{/link} fue destruido, Illidan vertió viales robados de sus aguas en un lago en la cima del {link:mount-hyjal}Monte Hyjal{/link}, y creó un nuevo Pozo. {link:malfurion-stormrage}Malfurion{/link} consideró aquello un crimen. Hizo encadenar a su hermano bajo tierra, custodiado por la celadora Maiev Shadowsong.]=],
		},
		{
			title = "La Tercera Guerra",
			text = [=[Diez mil años después, la {link:scourge}Plaga{/link} y la Legión llegaron a {link:kalimdor}Kalimdor{/link}. En contra de la ley de su pueblo, {link:tyrande-whisperwind}Tyrande{/link} liberó a Illidan para que ayudara. En el bosque que hoy se llama {link:felwood}Frondavil{/link}, consumió el Cráneo de {link:gul-dan}Gul'dan{/link}, adoptó la forma de un demonio y mató al señor del terror {link:tichondrius}Tichondrius{/link}. {link:malfurion-stormrage}Malfurion{/link} lo desterró de los bosques de los elfos de la noche.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Luchó contra {link:azshara}Azshara{/link} en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.
• Creó un nuevo {link:well-of-eternity}Pozo de la Eternidad{/link} en la cima del {link:mount-hyjal}Monte Hyjal{/link}.
• Consumió el {link:skull-of-gul-dan}Cráneo de Gul'dan{/link} y mató a {link:tichondrius}Tichondrius{/link}.
• Alzó a las nagas de las profundidades para que le sirvieran tras la {link:third-war}Tercera Guerra{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Tras su destierro, Illidan reunió a las {link:naga}nagas{/link} y buscó la Tumba de {link:sargeras}Sargeras{/link} bajo el mar. Lo persiguieron Maiev, y también su hermano y {link:tyrande-whisperwind}Tyrande{/link}, y escapó de todos ellos. Más tarde marchó sobre {red:northrend}Rasganorte{/red} para atacar al {red:lich-king}Rey Exánime{/red}. En el glaciar de Corona de Hielo, luchó contra {link:arthas-menethil}Arthas Menethil{/link} y fue derrotado. Huyó con sus seguidores supervivientes. Adónde fue después, ninguna crónica de los reinos sabe decirlo.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "su hermano gemelo" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "el amor que perdió" },
		{ id = "queen-azshara", name = "Reina Azshara", note = "antigua enemiga" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "lo derrotó en Corona de Hielo" },
		{ id = "gul-dan", name = "Gul'dan", note = "cuyo cráneo consumió" },
	},
})

Translate("esES", "malfurion-stormrage", {
	title = "Malfurion Stormrage",
	subtitle = "El primer druida",
	allegiance = "Elfos de la noche · Círculo Cenarion",
	aliases = { "Malfurion" },
	sections = {
		{
			title = "Resumen",
			text = [=[Malfurion Stormrage fue el primer druida {link:night-elves}elfo de la noche{/link}, alumno del semidiós {link:cenarius}Cenarius{/link} y hermano gemelo de {link:illidan-stormrage}Illidan Stormrage{/link}. Dirigió la lucha contra la {link:burning-legion}Legión Ardiente{/link} en la {link:war-of-the-ancients}Guerra de los Ancestros{/link} y de nuevo en la {link:third-war}Tercera Guerra{/link}. Es el amado de {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Ahora duerme en el {link:emerald-dream}Sueño Esmeralda{/link}, y su pueblo espera a que despierte.]=],
		},
		{
			title = "Importancia",
			text = [=[Malfurion salvó el mundo dos veces. En tiempos antiguos destruyó el {link:well-of-eternity}Pozo de la Eternidad{/link} para cerrar la puerta a la Legión. Diez mil años después destruyó a {link:archimonde}Archimonde{/link} al pie del Árbol del Mundo. Los druidas de todas las tierras siguen la senda que él recorrió por primera vez.]=],
		},
		{
			title = "La Guerra de los Ancestros",
			text = [=[Malfurion se sintió atraído por el mundo vivo mientras su hermano estudiaba lo arcano. {link:cenarius}Cenarius{/link} lo tomó como alumno y le enseñó a moldear los poderes de la naturaleza. Cuando la {link:queen-azshara}reina Azshara{/link} y sus Altonatos trajeron la Legión al mundo, Malfurion se unió a la resistencia. Vio que la Legión solo podía ser detenida destruyendo el propio {link:well-of-eternity}Pozo de la Eternidad{/link}. Su ataque contra él desencadenó la {link:great-sundering}Gran Fractura{/link}, que destrozó la tierra y ahogó la capital de la reina. Cuando {link:illidan-stormrage}Illidan{/link} creó un nuevo Pozo en el {link:mount-hyjal}Monte Hyjal{/link}, Malfurion hizo que lo encarcelaran. Con la ayuda de los grandes dragones, los supervivientes plantaron {link:nordrassil}Nordrassil{/link} sobre el nuevo Pozo. Después, Malfurion y sus druidas entraron en un largo sueño en el {link:emerald-dream}Sueño Esmeralda{/link}.]=],
		},
		{
			title = "La Tercera Guerra",
			text = [=[Cuando la Legión regresó, {link:tyrande-whisperwind}Tyrande{/link} despertó a los druidas. Malfurion los devolvió al mundo y ayudó a defender los bosques de {link:ashenvale}Vallefresno{/link} contra los demonios. En contra de su voluntad, Tyrande liberó a {link:illidan-stormrage}Illidan{/link}, y él llegó demasiado tarde para impedir que su hermano tomara el poder de un demonio. Desterró a Illidan y volvió a la defensa de Hyjal. Allí se mantuvo junto a los orcos de {link:thrall}Thrall{/link} y los hombres de {link:jaina-proudmoore}Jaina Proudmoore{/link}. Cuando {link:archimonde}Archimonde{/link} llegó a {link:nordrassil}Nordrassil{/link}, Malfurion hizo sonar el Cuerno de {link:cenarius}Cenarius{/link}. Los espíritus de los ancestros destruyeron al señor demoníaco, y el mundo se salvó.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Aprendió los caminos de la naturaleza de {link:cenarius}Cenarius{/link} y se convirtió en el primer druida.
• Destruyó el {link:well-of-eternity}Pozo de la Eternidad{/link} y puso fin a la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.
• Encarceló a su hermano bajo tierra.
• Dirigió a los druidas contra la Legión en la {link:third-war}Tercera Guerra{/link}.
• Destruyó a {link:archimonde}Archimonde{/link} en la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Tras la guerra, Malfurion persiguió a {link:illidan-stormrage}Illidan{/link} a través del mar, y después lo dejó marchar. Regresó al {link:emerald-dream}Sueño Esmeralda{/link} y no ha despertado desde entonces. En su ausencia, el archidruida {link:fandral-staghelm}Fandral Staghelm{/link} dirige a los druidas de {link:darnassus}Darnassus{/link}, y los elfos de la noche han plantado un nuevo Árbol del Mundo, {link:teldrassil}Teldrassil{/link}. {link:tyrande-whisperwind}Tyrande{/link} gobierna y espera.]=],
		},
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "su hermano gemelo" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "su amada" },
		{ id = "archimonde", name = "Archimonde", note = "el demonio al que destruyó" },
		{ id = "queen-azshara", name = "Reina Azshara", note = "la reina contra la que luchó" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "dirige a los druidas en su lugar" },
	},
})

Translate("esES", "queen-azshara", {
	title = "Reina Azshara",
	subtitle = "Reina de los Altonatos",
	allegiance = "Altonatos · Nagas",
	sections = {
		{
			title = "Resumen",
			text = [=[La reina {link:azshara}Azshara{/link} gobernó el antiguo imperio de los {link:night-elves}elfos de la noche{/link} en el apogeo de su gloria. Era la más bella y la más poderosa de su pueblo, y este la adoraba. Desde su palacio en Zin-Azshari, junto al {link:well-of-eternity}Pozo de la Eternidad{/link}, guio a los Altonatos en el estudio de la {link:arcane-magic}magia arcana{/link}. En su orgullo, abrió el mundo a la {link:burning-legion}Legión Ardiente{/link}, y su imperio se hundió bajo el mar.]=],
		},
		{
			title = "Importancia",
			text = [=[La traición de {link:azshara}Azshara{/link} dio comienzo a la {link:war-of-the-ancients}Guerra de los Ancestros{/link} y terminó en la {link:great-sundering}Gran Fractura{/link}. La forma quebrada de {link:kalimdor}Kalimdor{/link} y de los {link:eastern-kingdoms}Reinos del Este{/link} es su legado. Quizá también lo sean las {link:naga}nagas{/link} que ahora emergen de las olas.]=],
		},
		{
			title = "La reina de los Altonatos",
			text = [=[El pueblo de {link:azshara}Azshara{/link} puso su nombre a ciudades y montañas. Los Altonatos, la casta noble de su corte, la servían como sacerdotes y hechiceros. Bajo su gobierno bebieron cada vez más a fondo del {link:well-of-eternity}Pozo de la Eternidad{/link}. Sus hechizos llegaron más allá del mundo y atrajeron la mirada de {link:sargeras}Sargeras{/link}. El señor demoníaco susurró a la reina, y ella escuchó. Llegó a creer que el mundo debía ser limpiado de todos los pueblos inferiores, y que Sargeras lo haría posible.]=],
		},
		{
			title = "La Guerra de los Ancestros",
			text = [=[{link:azshara}Azshara{/link} y sus Altonatos abrieron un portal dentro del Pozo, y los demonios de la Legión entraron en tropel. Su consejero Xavius la sirvió en esta obra. Los elfos de la noche que seguían libres se alzaron contra su reina, dirigidos por {link:malfurion-stormrage}Malfurion Stormrage{/link}, {link:tyrande-whisperwind}Tyrande Whisperwind{/link} y lord Kur'talos Ravencrest. Mientras la guerra hacía estragos, los Altonatos trabajaban para traer al mundo al propio {link:sargeras}Sargeras{/link}. Solo se les detuvo cuando el Pozo fue destruido. Su derrumbe desgarró la tierra, y el mar se precipitó sobre Zin-Azshari.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Gobernó a los elfos de la noche en el apogeo de su poder.
• Guio a los Altonatos en el uso del {link:well-of-eternity}Pozo de la Eternidad{/link}.
• Abrió el camino de la {link:burning-legion}Legión Ardiente{/link} hacia {link:azeroth}Azeroth{/link}.
• Intentó traer al mundo al propio {link:sargeras}Sargeras{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Cuando el Pozo se derrumbó, Azshara y sus Altonatos desaparecieron bajo las olas. Las leyendas de los elfos de la noche dicen que no murieron, sino que cambiaron, y que las nagas serpentinas son aquello en lo que se convirtieron. Las nagas han vuelto a las costas en estos días, y asaltan las orillas de {link:kalimdor}Kalimdor{/link} y de otras tierras. Algunas hablan de su antigua reina como si aún viviera. Solo quedan las ruinas de su imperio en la tierra que lleva su nombre, {link:azshara}Azshara{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ningún registro mortal dice si {link:azshara}Azshara{/link} sigue viva bajo el mar, ni en qué se ha convertido.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "dirigió la rebelión contra ella" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "luchó contra su corte" },
		{ id = "archimonde", name = "Archimonde", note = "un señor de la Legión a la que sirvió" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "dirigió la rebelión contra ella" },
	},
})

Translate("esES", "deathwing", {
	title = "Alamuerte",
	subtitle = "El Destructor",
	allegiance = "Vuelo Negro",
	aliases = { "Neltharion" },
	sections = {
		{
			title = "Resumen",
			text = [=[Alamuerte fue en otro tiempo Neltharion, el Guardián de la Tierra, Aspecto del Vuelo Negro. Tenía el encargo de proteger los lugares profundos del mundo. La locura se apoderó de él, y traicionó a los demás vuelos de dragones en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}. Desde entonces ha conspirado contra todos los pueblos de {link:azeroth}Azeroth{/link}. Su nombre significa ruina para dragones y mortales por igual.]=],
		},
		{
			title = "Importancia",
			text = [=[La traición de Alamuerte estuvo a punto de destruir a los vuelos de dragones. Su intromisión en la {link:second-war}Segunda Guerra{/link} dio a la {link:horde}Horda{/link} sus dragones. Su progenie negra aún ronda la {link:blackrock-mountain}Montaña Roca Negra{/link} y otros lugares oscuros del mundo.]=],
		},
		{
			title = "El Guardián de la Tierra",
			text = [=[En los días antiguos, cinco grandes dragones fueron elegidos como Aspectos para proteger el mundo. A Neltharion se le dio dominio sobre la tierra y sus profundidades. Algo le susurró desde muy por debajo de la piedra, y con el tiempo su mente se trastornó. En la {link:war-of-the-ancients}Guerra de los Ancestros{/link} forjó un gran disco de oro, el Alma de {link:the-drag}Drag{/link}ón. Convenció a los demás Aspectos de que le entregaran parte de su poder, diciéndoles que rechazaría a la {link:burning-legion}Legión Ardiente{/link}. En cambio, lo volvió contra ellos. El poder del artefacto era tan grande que su cuerpo empezó a desgarrarse, y se le fijaron placas de metal a la piel para mantenerlo entero. Huyó, y el Alma de Dragón se perdió.]=],
		},
		{
			title = "La Segunda Guerra",
			text = [=[Alamuerte lleva mucho tiempo caminando entre los mortales con disfraz humano, como un noble que se mueve por las cortes de los reyes. Las historias dicen que sembraba la discordia allí donde podía. En la {link:second-war}Segunda Guerra{/link}, el Alma de {link:the-drag}Drag{/link}ón cayó en manos de los {link:dragonmaw-clan}orcos Faucedraco{/link}. Con ella capturaron a {link:alexstrasza}Alexstrasza{/link}, Aspecto de los dragones rojos, y la retuvieron bajo {link:grim-batol}Grim Batol{/link}. Sus crías fueron criadas como monturas de guerra para la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Traicionó a los Aspectos con el Alma de {link:the-drag}Drag{/link}ón en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.
• Se movió en secreto por las cortes de los hombres.
• Dejó que el Alma de Dragón cayera en manos del {link:dragonmaw-clan}clan Faucedraco{/link}.
• Intentó robar los huevos del Vuelo Rojo de {link:grim-batol}Grim Batol{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Tras la {link:second-war}Segunda Guerra{/link}, los Faucedraco aún mantenían cautiva a {link:alexstrasza}Alexstrasza{/link} en {link:grim-batol}Grim Batol{/link}. Alamuerte fue a por sus huevos, con la intención de reconstruir su propio vuelo. Una pequeña banda de héroes y dragones liberó a la reina roja, y el Alma de {link:the-drag}Drag{/link}ón fue destruida. Alamuerte fue expulsado, lleno de furia. Nadie sabe adónde fue. La montaña de Grim Batol, en {link:wetlands}Los Humedales{/link}, sigue siendo evitada por los enanos hasta hoy. Sus hijos y su Vuelo Negro siguen sueltos por el mundo.]=],
		},
	},
	bonds = {
		{ id = "alexstrasza", name = "Alexstrasza", note = "el Aspecto al que ayudó a esclavizar" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "Jefe de Guerra de la Horda que usó su regalo" },
		{ id = "queen-azshara", name = "Reina Azshara", note = "aliada de la Legión contra la que decía luchar" },
	},
})

Translate("esES", "kel-thuzad", {
	title = "Kel'Thuzad",
	subtitle = "Fundador del Culto de los Malditos",
	allegiance = "Plaga · Culto de los Malditos (antes Kirin Tor)",
	sections = {
		{
			title = "Resumen",
			text = [=[Kel'Thuzad fue en otro tiempo un archimago de {link:city-of-dalaran}Dalaran{/link} y miembro del consejo gobernante del {link:kirin-tor}Kirin Tor{/link}. Se volvió hacia el arte prohibido de la nigromancia, se entregó al {red:lich-king}Rey Exánime{/red} y fundó el {link:cult-of-the-damned}Culto de los Malditos{/link}. Propagó la plaga que destruyó {link:lordaeron}Lordaeron{/link}. Muerto a manos del príncipe {link:arthas-menethil}Arthas Menethil{/link}, se alzó de nuevo como liche. Ahora dirige la {link:scourge}Plaga{/link} en Lordaeron en nombre de su amo.]=],
		},
		{
			title = "Importancia",
			text = [=[Sin Kel'Thuzad, la plaga de no-muerte quizá nunca habría alcanzado al pueblo de {link:lordaeron}Lordaeron{/link}. Fue la voz del Rey Exánime entre los vivos, y abrió el camino para que la {link:burning-legion}Legión Ardiente{/link} regresara a {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "El archimago",
			text = [=[Kel'Thuzad era uno de los mayores {link:the-wizards-of-ambermill}magos de Dalaran{/link}, pero creía que sus colegas eran demasiado tímidos en sus estudios. Empezó a ahondar en el arte oscuro de la nigromancia. Cuando el consejo la prohibió, no se detuvo. Una voz lo llamó desde {red:northrend}Rasganorte{/red}. Respondió, viajó al norte helado y se entregó al Rey Exánime. Su amo le prometió la vida eterna.]=],
		},
		{
			title = "El Culto de los Malditos",
			text = [=[Kel'Thuzad regresó a {link:lordaeron}Lordaeron{/link} y habló a los pobres y a los cansados de una nueva sociedad donde todos serían iguales y nadie moriría. Miles se unieron a su {link:cult-of-the-damned}Culto de los Malditos{/link}. A través de ellos, contaminó el grano de los graneros del norte con una plaga que convertía a los vivos en no-muertos. Cuando {link:arthas-menethil}Arthas{/link} llegó al norte para combatir la plaga, encontró a Kel'Thuzad en {link:ruins-of-andorhal}Andorhal{/link} y lo mató. Pero el espíritu del nigromante permaneció, y susurró al príncipe mientras este caía.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudió la nigromancia desafiando al {link:kirin-tor}Kirin Tor{/link}.
• Se entregó al Rey Exánime en Rasganorte.
• Fundó el {link:cult-of-the-damned}Culto de los Malditos{/link}.
• Propagó la plaga de no-muerte por el grano de {link:lordaeron}Lordaeron{/link}.
• Invocó a {link:archimonde}Archimonde{/link} en {link:city-of-dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Cuando {link:arthas-menethil}Arthas{/link} se convirtió en siervo del Rey Exánime, llevó los restos del nigromante a {link:quel-thalas}Quel'Thalas{/link}. Allí, en las aguas de la Fuente del Sol, Kel'Thuzad renació como liche. Con el libro de hechizos de {link:medivh}Medivh{/link}, invocó a {link:archimonde}Archimonde{/link} en {link:city-of-dalaran}Dalaran{/link}, y el señor demoníaco redujo la ciudad a ruinas. Cuando Arthas regresó a Rasganorte, Kel'Thuzad se quedó para gobernar la {link:scourge}Plaga{/link} en {link:lordaeron}Lordaeron{/link}. Todavía lo hace. La gran necrópolis de {red:naxxramas}Naxxramas{/red} flota sobre las Tierras de la Peste, y sus sectarios mantienen su escuela de saber oscuro en el viejo castillo de {link:caer-darrow}Castel Darrow{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "su verdugo, y después su amo" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "el Rey Exánime al que juró lealtad" },
		{ id = "archimonde", name = "Archimonde", note = "el demonio al que invocó" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "cuyas cenizas dejaron sitio a sus huesos" },
	},
})

Translate("esES", "jaina-proudmoore", {
	title = "Jaina Proudmoore",
	subtitle = "Soberana de Theramore",
	found = "Ciudadela Garrida, Isla Theramore, en Marjal Revolcafango",
	hint = [=[Busque a la dama de Theramore en la torre de la ciudadela de su isla.]=],
	allegiance = "Theramore · Alianza · Kirin Tor",
	aliases = { "Jaina", "Lady Jaina Proudmoore", "Lady Proudmoore" },
	sections = {
		{
			title = "Resumen",
			text = [=[Lady Jaina Proudmoore gobierna {link:theramore-isle}Theramore{/link}, la fortaleza isleña de la {link:alliance}Alianza{/link} en la costa oriental de {link:kalimdor}Kalimdor{/link}. Es hija del lord almirante {link:daelin-proudmoore}Daelin Proudmoore{/link} de {link:kul-tiras}Kul Tiras{/link} y una hechicera instruida en {link:city-of-dalaran}Dalaran{/link} por el {link:kirin-tor}Kirin Tor{/link}. Caminó junto al príncipe {link:arthas-menethil}Arthas Menethil{/link} en los días de la plaga, y se separó de él antes de su caída. Condujo a los supervivientes del norte a través del mar, e hizo con la {link:horde}Horda{/link} una paz que nadie antes que ella había creído posible.]=],
		},
		{
			title = "Importancia",
			text = [=[Jaina es el puente entre los viejos enemigos. Estuvo junto a {link:thrall}Thrall{/link} en la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, y todavía le es fiel. Esa paz le costó su padre. Es frágil, y muchos en ambos bandos querrían verla rota.]=],
		},
		{
			title = "La plaga",
			text = [=[De joven, Jaina estudió magia en {link:city-of-dalaran}Dalaran{/link} con el archimago Antonidas, y mostró dotes poco comunes. Cuando una extraña plaga se extendió por las tierras de cultivo del norte de {link:lordaeron}Lordaeron{/link}, fue con el príncipe {link:arthas-menethil}Arthas{/link} a buscar su origen. Juntos descubrieron el {link:cult-of-the-damned}Culto de los Malditos{/link} y el grano contaminado. En Stratholme, Arthas ordenó que el pueblo de la ciudad fuera ejecutado antes de que pudiera alzarse como no-muerto. Jaina no quiso participar, y lo dejó allí. La {link:culling-of-stratholme}Matanza de Stratholme{/link} siguió adelante sin ella.]=],
		},
		{
			title = "El viaje al oeste",
			text = [=[Un misterioso profeta instó a los líderes del este a navegar hacia el oeste a través del mar. Jaina le hizo caso cuando otros no lo hicieron, y condujo a los supervivientes de {link:lordaeron}Lordaeron{/link} hasta {link:kalimdor}Kalimdor{/link}. Allí conoció a {link:thrall}Thrall{/link} y a sus orcos, los viejos enemigos de su pueblo. El profeta los unió contra un enemigo mayor, y en el {link:mount-hyjal}Monte Hyjal{/link} humanos, orcos y {link:night-elves}elfos de la noche{/link} lucharon codo con codo hasta que {link:archimonde}Archimonde{/link} fue destruido.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudió magia entre el {link:kirin-tor}Kirin Tor{/link} de {link:city-of-dalaran}Dalaran{/link}.
• Persiguió la plaga con {link:arthas-menethil}Arthas{/link} y rechazó la {link:culling-of-stratholme}Matanza de Stratholme{/link}.
• Condujo a los supervivientes de {link:lordaeron}Lordaeron{/link} hacia el oeste, hasta {link:kalimdor}Kalimdor{/link}.
• Luchó junto a {link:thrall}Thrall{/link} y los elfos de la noche en el {link:mount-hyjal}Monte Hyjal{/link}.
• Fundó {link:theramore-isle}Theramore{/link} e hizo la paz con la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Theramore",
			text = [=[Tras la guerra, Jaina levantó {link:theramore-isle}Theramore{/link} en una isla frente a la costa de {link:dustwallow-marsh}Marjal Revolcafango{/link}. Entonces su padre llegó a {link:kalimdor}Kalimdor{/link} con una gran flota. {link:daelin-proudmoore}Daelin{/link} no quiso aceptar una paz con los orcos, y les hizo la guerra. Jaina no pudo convencerlo de que se detuviera. No quiso dejar que destruyera la paz, y se mantuvo al margen mientras la {link:horde}Horda{/link} se defendía. Daelin murió en los combates ante las murallas de Theramore. Su hija lo llora, y los marineros que lo siguieron no la han perdonado.]=],
		},
		{
			title = "El presente",
			text = [=[Jaina gobierna {link:theramore-isle}Theramore{/link} desde su ciudadela. La ciudad es un refugio para el pueblo del norte perdido, y una puerta de la {link:alliance}Alianza{/link} hacia {link:kalimdor}Kalimdor{/link}. Mantiene la paz con {link:thrall}Thrall{/link} lo mejor que puede, mientras los soldados de ambos bandos chocan en las tierras salvajes.]=],
		},
	},
	chapters = {
		{
			title = "El diplomático desaparecido",
			hint = "Siga el rastro del diplomático desaparecido hasta Theramore.",
			text = [=[El rastro de un enviado secuestrado llevaba desde {link:stormwind-city}Ventormenta{/link} hasta el {link:menethil-harbor}Puerto de Menethil{/link}, y de allí, a través del mar, hasta {link:dustwallow-marsh}Marjal Revolcafango{/link}. Al final del rastro estaba el soldado {link:private-hendel}Hendel{/link}, un soldado de {link:theramore-isle}Theramore{/link} que se había vendido a la {link:defias-brotherhood}Hermandad Defias{/link}. Cuando fue desenmascarado, desenvainó su espada. Jaina y sus guardias acudieron para prenderlo vivo, pues un traidor muerto no cuenta nada. La dama de Theramore dio las gracias en voz baja a quienes habían sacado la verdad a la luz. No podía darles las gracias abiertamente. Lo que Hendel sabe del rey desaparecido de Ventormenta es asunto de sus interrogadores.]=],
		},
	},
	mentions = {
		{ text = "The Missing Diplomat" },
		{ text = "The Missing Diplomat" },
	},
	bonds = {
		{ id = "daelin-proudmoore", name = "Daelin Proudmoore", note = "su padre" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "su compañero, y su amor perdido" },
		{ id = "thrall", name = "Thrall", note = "su aliado en la paz" },
		{ id = "aegwynn", name = "Aegwynn", note = "se dice que la aconsejó" },
		{ id = "tapoke-slim-jahn", name = "Tapoke \"Slim\" Jahn", note = "ayudó en la conspiración que descubrieron sus guardias" },
	},
})

Translate("esES", "khadgar", {
	title = "Khadgar",
	subtitle = "Aprendiz del último Guardián",
	allegiance = "Kirin Tor · Alianza de Lordaeron",
	sections = {
		{
			title = "Resumen",
			text = [=[Khadgar fue un joven mago de {link:city-of-dalaran}Dalaran{/link} enviado por el {link:kirin-tor}Kirin Tor{/link} para servir como aprendiz a {link:medivh}Medivh{/link}, el último Guardián de {link:tirisfal-glades}Tirisfal{/link}. Fue el primero en ver que el propio Guardián había traído a los orcos a {link:azeroth}Azeroth{/link}. Luchó en la {link:first-war}Primera Guerra{/link} y en la {link:second-war}Segunda Guerra{/link}, y se convirtió en uno de los grandes archimagos de su tiempo. Cruzó el {link:dark-portal}Portal Oscuro{/link} hace mucho tiempo, y no ha regresado.]=],
		},
		{
			title = "Importancia",
			text = [=[Khadgar sacó la verdad de {link:karazhan}Karazhan{/link}. Sin él, {link:stormwind-city}Ventormenta{/link} quizá nunca habría sabido quién era su verdadero enemigo. En la {link:second-war}Segunda Guerra{/link} estuvo junto a {link:anduin-lothar}Anduin Lothar{/link} como uno de los líderes de la {link:alliance}Alianza{/link}, y al final cerró el camino entre los mundos a costa de su propio regreso.]=],
		},
		{
			title = "Karazhan",
			text = [=[Los {link:the-wizards-of-ambermill}magos de Dalaran{/link} deseaban desde hacía tiempo conocer los secretos de la {link:karazhan}torre de Medivh{/link}. Enviaron a Khadgar como su aprendiz, y le pidieron que observara. El Guardián lo acogió y lo instruyó. Khadgar pronto descubrió que su maestro guardaba largos silencios, tenía visiones extrañas y una oscuridad de la que no quería hablar. Con la semiorca {link:garona}Garona{/link}, que llegó a la torre como enviada de la {link:horde}Horda{/link}, descubrió que el propio {link:medivh}Medivh{/link} había abierto el {link:dark-portal}Portal Oscuro{/link}. Los dos llevaron el aviso al rey {link:llane-wrynn}Llane Wrynn{/link}. Después, Khadgar subió a Karazhan con {link:anduin-lothar}Lothar{/link} para enfrentarse a su maestro. Medivh murió. En aquella batalla el joven mago envejeció muchos años en un instante, y bajó de la torre con el rostro de un anciano.]=],
		},
		{
			title = "La Segunda Guerra",
			text = [=[Khadgar fue al norte con {link:anduin-lothar}Lothar{/link} y los exiliados de {link:stormwind-city}Ventormenta{/link}. En {link:lordaeron}Lordaeron{/link} fue uno de los lugartenientes del campeón, junto con el paladín {link:turalyon}Turalyon{/link}. Combatió a la {link:horde}Horda{/link} por los reinos del norte y ayudó a lograr su derrota en la {link:blackrock-mountain}Montaña Roca Negra{/link}. Cuando se ganó la guerra, la {link:alliance}Alianza{/link} destruyó el {link:dark-portal}Portal Oscuro{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue el último aprendiz de {link:medivh}Medivh{/link} en {link:karazhan}Karazhan{/link}.
• Descubrió el papel de Medivh en la llegada de los orcos y advirtió al rey {link:llane-wrynn}Llane{/link}.
• Luchó junto a {link:anduin-lothar}Anduin Lothar{/link} cuando Medivh murió.
• Fue lugarteniente de la {link:alliance}Alianza{/link} en la {link:second-war}Segunda Guerra{/link}.
• Condujo a la Alianza más allá del {link:dark-portal}Portal Oscuro{/link} tras la guerra.]=],
		},
		{
			title = "Más allá del Portal",
			text = [=[Algunos años después de la {link:second-war}Segunda Guerra{/link}, el Portal se abrió de nuevo. Por él llegaron orcos de {red:draenor}Draenor{/red} para robar reliquias de poder, enviados por el viejo chamán {link:ner-zhul}Ner'zhul{/link}. La {link:alliance}Alianza{/link} envió un ejército tras ellos al mundo natal de los orcos. Khadgar lo dirigió con {link:turalyon}Turalyon{/link}. Los hechizos de Ner'zhul destrozaron Draenor. Para impedir que la ruina se extendiera a {link:azeroth}Azeroth{/link}, los líderes de la Alianza decidieron cerrar el Portal desde el otro lado. Sabían que no podrían volver a casa. El Portal quedó en silencio, y la expedición se perdió para su pueblo.]=],
		},
		{
			title = "Destino",
			text = [=[Ninguna noticia de Khadgar ha llegado a los reinos desde que se cerró el Portal. En {link:blasted-lands}Las Tierras Devastadas{/link}, los magos del {link:kirin-tor}Kirin Tor{/link} vigilan la puerta en ruinas desde la fortaleza de {link:nethergarde-keep}Nethergarde{/link}, y no lo han olvidado.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de los reinos cuenta qué fue de Khadgar y sus compañeros más allá del Portal.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "su maestro" },
		{ id = "garona", name = "Garona", note = "su aliada en Karazhan" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "su comandante" },
		{ id = "turalyon", name = "Turalyon", note = "su compañero en dos guerras" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "su enemigo más allá del Portal" },
	},
})

Translate("esES", "turalyon", {
	title = "Turalyon",
	subtitle = "Vencedor de la Segunda Guerra",
	allegiance = "Caballeros de la Mano de Plata · Alianza de Lordaeron",
	sections = {
		{
			title = "Resumen",
			text = [=[Turalyon fue un joven sacerdote de la {link:holy-light}Luz Sagrada{/link} que se convirtió en uno de los primeros paladines de los Caballeros de la Mano de Plata. Sirvió como lugarteniente de {link:anduin-lothar}Anduin Lothar{/link} en la {link:second-war}Segunda Guerra{/link}. Cuando Lothar cayó, Turalyon asumió su mando y ganó la guerra. Después condujo a la {link:alliance}Alianza{/link} más allá del {link:dark-portal}Portal Oscuro{/link}, y no regresó.]=],
		},
		{
			title = "Importancia",
			text = [=[Fue Turalyon quien convirtió la hora más oscura de la {link:alliance}Alianza{/link} en victoria. Su carga en la {link:blackrock-mountain}Montaña Roca Negra{/link} quebró a la antigua {link:horde}Horda{/link}, y la paz que los reinos del norte conocieron durante una generación fue obra suya.]=],
		},
		{
			title = "La Mano de Plata",
			text = [=[Turalyon era sacerdote de la iglesia en {link:lordaeron}Lordaeron{/link} cuando los exiliados de {link:stormwind-city}Ventormenta{/link} llegaron al norte. {link:anduin-lothar}Lothar{/link} vio fuerza en él y lo hizo uno de sus lugartenientes, junto con el mago {link:khadgar}Khadgar{/link}. Turalyon dudaba de sí mismo y de su fe. Sin embargo, estuvo entre los primeros caballeros a los que el arzobispo {link:alonsus-faol}Alonsus Faol{/link} enseñó a esgrimir la Luz en la batalla, con {link:uther-the-lightbringer}Uther el Iluminado{/link}, {link:tirion-fordring}Tirion Fordring{/link} y unos pocos más. Dirigió los ejércitos de la {link:alliance}Alianza{/link} contra la {link:horde}Horda{/link} en el norte, y aprendió a confiar en el poder que se le había dado.]=],
		},
		{
			title = "La Montaña Roca Negra",
			text = [=[Al final de la guerra, la {link:alliance}Alianza{/link} empujó a la {link:horde}Horda{/link} hacia el sur, hasta la {link:blackrock-mountain}Montaña Roca Negra{/link}. En la batalla al pie de la montaña, el Jefe de Guerra {link:orgrim-doomhammer}Orgrim Doomhammer{/link} mató a {link:anduin-lothar}Lothar{/link}. Los soldados de la Alianza vacilaron. Turalyon tomó la espada de su comandante y los reagrupó. Los paladines invocaron la Luz, y la Horda fue quebrada. Doomhammer fue hecho prisionero. Turalyon persiguió a los últimos orcos hasta el {link:dark-portal}Portal Oscuro{/link}, y la Alianza destruyó la puerta.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estuvo entre los primeros paladines de la Mano de Plata.
• Sirvió como lugarteniente de {link:anduin-lothar}Anduin Lothar{/link} en la {link:second-war}Segunda Guerra{/link}.
• Reagrupó a la {link:alliance}Alianza{/link} tras la muerte de Lothar y ganó la batalla de la {link:blackrock-mountain}Montaña Roca Negra{/link}.
• Empujó a la {link:horde}Horda{/link} hasta el {link:dark-portal}Portal Oscuro{/link} y vio su destrucción.
• Condujo el ejército de la Alianza a {red:draenor}Draenor{/red} con {link:khadgar}Khadgar{/link}.]=],
		},
		{
			title = "Más allá del Portal",
			text = [=[Algunos años después, el Portal se abrió de nuevo, y por él llegaron orcos para robar reliquias de poder para el chamán {link:ner-zhul}Ner'zhul{/link}. Turalyon condujo el ejército de la {link:alliance}Alianza{/link} a Draenor con {link:khadgar}Khadgar{/link}. Con ellos fueron la forestal Alleria Windrunner, hermana mayor de {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, y otros héroes de la guerra. La expedición combatió a los orcos por todo su mundo quebrado. Cuando los hechizos de Ner'zhul empezaron a destrozar Draenor, sus líderes cerraron el Portal desde el otro lado para que la ruina no alcanzara {link:azeroth}Azeroth{/link}. No pudieron volver a casa.]=],
		},
		{
			title = "Destino",
			text = [=[Turalyon no ha sido visto en los reinos desde que se cerró el Portal. Los paladines del norte aún pronuncian su nombre junto al de {link:uther-the-lightbringer}Uther{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de los reinos recoge qué fue de Turalyon más allá del Portal.]=],
		},
	},
	bonds = {
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "su comandante" },
		{ id = "khadgar", name = "Khadgar", note = "su compañero en dos guerras" },
		{ id = "uther-the-lightbringer", name = "Uther el Iluminado", note = "un hermano de la Mano de Plata" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "el Jefe de Guerra al que derrotó" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "lo ordenó" },
	},
})

Translate("esES", "tirion-fordring", {
	title = "Tirion Fordring",
	subtitle = "El paladín exiliado",
	found = [=[Una cabaña solitaria junto al río, en el borde occidental de las Tierras de la Peste del Este]=],
	hint = [=[Busque al ermitaño que pesca junto a una cabaña en el borde occidental de las Tierras de la Peste del Este.]=],
	allegiance = "Ninguna (antes los Caballeros de la Mano de Plata)",
	aliases = { "Tirion" },
	sections = {
		{
			title = "Resumen",
			text = [=[Tirion Fordring fue en otro tiempo señor del Fuerte de Mardenholde y uno de los primeros paladines de la Mano de Plata. Fue despojado de sus tierras y títulos por defender a un {link:orcs}orco{/link}, y enviado al exilio. Ahora vive solo en una cabaña en las {link:eastern-plaguelands}Tierras de la Peste del Este{/link}, un anciano en una tierra de muertos. Su hijo dirige la {link:scarlet-crusade}Cruzada Escarlata{/link} en {link:hearthglen}Vega del Amparo{/link}, y cree que su padre murió hace mucho.]=],
		},
		{
			title = "Importancia",
			text = [=[Tirion es un hombre de la Luz que conservó su honor cuando su orden y su reino no lo hicieron. Pocos en {link:lordaeron}Lordaeron{/link} lo recuerdan. Sin embargo, los orcos que conocen su historia lo honran, y la historia de su caída habla a cualquiera que haya tenido que elegir entre la ley y lo que es justo.]=],
		},
		{
			title = "La Mano de Plata",
			text = [=[Tirion estuvo entre los primeros caballeros instruidos por el arzobispo {link:alonsus-faol}Alonsus Faol{/link}, con {link:uther-the-lightbringer}Uther el Iluminado{/link} y {link:turalyon}Turalyon{/link}. Combatió a la {link:horde}Horda{/link} en la {link:second-war}Segunda Guerra{/link}. Tras la guerra gobernó las tierras de {link:hearthglen}Vega del Amparo{/link} desde el Fuerte de Mardenholde con su esposa, Karandra, y su hijo, {link:taelan-fordring}Taelan{/link}.]=],
		},
		{
			title = "El juicio",
			text = [=[Un día Tirion se topó con un viejo guerrero {link:orcs}orco{/link} escondido en unas ruinas cerca de sus tierras. Era {link:eitrigg}Eitrigg{/link}. El orco podría haberlo matado, y en cambio le perdonó la vida. Tirion vio honor en él y lo dejó ir. Cuando sus propios soldados fueron a matar al orco, Tirion lo defendió. Por ello fue juzgado por traición. Fue despojado de sus tierras y títulos y expulsado de la orden. Su esposa dijo a su hijo que había muerto, y llevaron a {link:taelan-fordring}Taelan{/link} a la falsa tumba de su padre.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estuvo entre los primeros paladines de los Caballeros de la Mano de Plata.
• Combatió a la {link:horde}Horda{/link} en la {link:second-war}Segunda Guerra{/link}.
• Gobernó el Fuerte de Mardenholde y las tierras en torno a {link:hearthglen}Vega del Amparo{/link}.
• Perdonó la vida al {link:orcs}orco{/link} {link:eitrigg}Eitrigg{/link} y lo defendió contra sus propios hombres.]=],
		},
		{
			title = "El presente",
			text = [=[Tirion vive solo junto al río, lejos de cualquier camino. Su hijo {link:taelan-fordring}Taelan{/link} se hizo paladín y ahora es alto señor de la {link:scarlet-crusade}Cruzada Escarlata{/link} en {link:hearthglen}Vega del Amparo{/link}, atado a una orden que ha perdido el rumbo. {link:eitrigg}Eitrigg{/link} sirve a {link:thrall}Thrall{/link} en {link:orgrimmar}Orgrimmar{/link} y no ha olvidado al hombre que lo salvó.]=],
		},
	},
	chapters = {
		{
			title = "Redención",
			hint = "Siéntese con el anciano junto al río y escuche su historia.",
			text = [=[Tirion solo pidió a su invitado que se sentara y escuchara. Habló de su caída y de su hijo, que había crecido sin él. No pidió que se limpiara su propio nombre. Pidió que {link:taelan-fordring}Taelan{/link} fuera salvado de aquello en lo que la Cruzada lo había convertido.]=],
		},
		{
			title = "De recuerdos olvidados",
			hint = [=[Recupere un juguete de una tumba falsa en el sur de las Tierras de la Peste.]=],
			text = [=[Cuando {link:taelan-fordring}Taelan{/link} tenía siete años, su padre le regaló un pequeño martillo de guerra, una copia del suyo. Tras el destierro de Tirion, el niño lo enterró en la falsa tumba de su padre en {link:the-undercroft}La Subgranja{/link}. Había permanecido allí desde entonces, y Tirion pidió que se lo devolvieran.]=],
		},
		{
			title = "Del honor perdido",
			hint = "Recupere lo que Taelan arrojó en Vallenorte.",
			text = [=[Cuando {link:uther-the-lightbringer}Uther{/link} cayó y la Mano de Plata fue destruida, el joven {link:taelan-fordring}Taelan{/link} siguió luchando tanto como pudo. En la aldea de {link:northdale}Vallenorte{/link} resistió por última vez, y allí arrojó al suelo el estandarte de la orden y le dio la espalda. Tirion contempló el estandarte desgarrado y recordó el día en que prestó su propio juramento.]=],
		},
		{
			title = "En sueños",
			hint = "Lleve a Taelan ante su padre.",
			text = [=[{link:taelan-fordring}Taelan{/link} había soñado con su padre durante años. Recordando lo que había sido, dejó {link:hearthglen}Vega del Amparo{/link} para buscarlo. La Cruzada le dio caza en el camino, y el gran inquisidor Isillien lo mató delante de su padre. En su dolor, Tirion declaró que la orden a la que había servido no estaba muerta. Se proclamó alto señor de una nueva Mano de Plata, renacida de la antigua.]=],
		},
	},
	mentions = {
		{ text = "Redemption" },
		{ text = "Of Forgotten Memories" },
		{ text = "Of Lost Honor" },
		{ text = "Del amor y la familia" },
		{ text = "In Dreams" },
	},
	bonds = {
		{ id = "eitrigg", name = "Eitrigg", note = "el orco al que perdonó la vida" },
		{ id = "uther-the-lightbringer", name = "Uther el Iluminado", note = "un hermano de la Mano de Plata" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "su maestro en la Luz" },
		{ id = "turalyon", name = "Turalyon", note = "un hermano de la Mano de Plata" },
	},
})

Translate("esES", "garona", {
	title = "Garona",
	subtitle = "La semiorca",
	allegiance = "Desconocida (antes el Consejo de la Sombra)",
	sections = {
		{
			title = "Resumen",
			text = [=[Garona era una semiorca de sangre mestiza, espía y enviada de la {link:horde}Horda{/link} en la {link:first-war}Primera Guerra{/link}. El brujo {link:gul-dan}Gul'dan{/link} la envió a la torre de {link:medivh}Medivh{/link}. Allí trabó amistad con el joven mago {link:khadgar}Khadgar{/link}, y llegó a servir al rey {link:llane-wrynn}Llane Wrynn{/link} de {link:stormwind-city}Ventormenta{/link}. También lo asesinó.]=],
		},
		{
			title = "Importancia",
			text = [=[Garona ayudó a llevar a {link:stormwind-city}Ventormenta{/link} la verdad sobre la traición de {link:medivh}Medivh{/link}, y asestó el golpe que acabó con su rey. Ambos actos fueron suyos, y ninguno lo fue del todo.]=],
		},
		{
			title = "Enviada y espía",
			text = [=[Garona era despreciada entre los orcos por su sangre mestiza, y aprendió pronto a sobrevivir con su ingenio. El {link:shadow-council}Consejo de la Sombra{/link} de {link:gul-dan}Gul'dan{/link} se sirvió de ella. Llegó a {link:karazhan}Karazhan{/link} como enviada de la {link:horde}Horda{/link} ante el Guardián. Allí ella y {link:khadgar}Khadgar{/link} descubrieron que el propio {link:medivh}Medivh{/link} había traído a los orcos a {link:azeroth}Azeroth{/link}. Estuvo con Khadgar y {link:anduin-lothar}Anduin Lothar{/link} cuando el Guardián murió. Después entró al servicio de {link:stormwind-city}Ventormenta{/link} y se convirtió en una consejera de confianza del rey.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue la enviada de la {link:horde}Horda{/link} ante {link:medivh}Medivh{/link} en {link:karazhan}Karazhan{/link}.
• Ayudó a {link:khadgar}Khadgar{/link} a descubrir la traición de Medivh.
• Estuvo presente en la muerte del Guardián.
• Mató al rey {link:llane-wrynn}Llane Wrynn{/link} en su propio castillo.]=],
		},
		{
			title = "Destino",
			text = [=[La mente de Garona no le pertenecía. Los brujos del {link:shadow-council}Consejo de la Sombra{/link} tenían un poder oculto sobre su voluntad. Cuando {link:orgrim-doomhammer}Orgrim Doomhammer{/link} sitió {link:stormwind-city}Ventormenta{/link} por última vez, ella mató a {link:llane-wrynn}Llane{/link} en su cámara, y el joven príncipe {link:varian-wrynn}Varian Wrynn{/link} lo vio. Después huyó. Nadie en los reinos sabe adónde fue.]=],
		},
		{
			title = "Sin registro",
			text = [=[Adónde ha ido Garona desde la caída de {link:stormwind-city}Ventormenta{/link}, y si aún vive, las crónicas no lo dicen.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "su rey, y su víctima" },
		{ id = "khadgar", name = "Khadgar", note = "su amigo en Karazhan" },
		{ id = "medivh", name = "Medivh", note = "el Guardián ante quien fue enviada" },
		{ id = "gul-dan", name = "Gul'dan", note = "su amo" },
	},
})

Translate("esES", "alexstrasza", {
	title = "Alexstrasza",
	subtitle = "Reina de los dragones rojos",
	allegiance = "Vuelo Rojo",
	aliases = { "Alexstrasza la Protectora" },
	sections = {
		{
			title = "Resumen",
			text = [=[Alexstrasza es el Aspecto del Vuelo Rojo, la Reina {link:the-drag}Drag{/link}ón, guardiana de la vida. En los días antiguos, los creadores del mundo le dieron poder sobre todos los seres vivos. Ha velado por {link:azeroth}Azeroth{/link} desde antes de que los elfos construyeran sus primeras ciudades. En los años de la {link:second-war}Segunda Guerra{/link} fue prisionera de los orcos, y sus hijos fueron convertidos en armas de guerra.]=],
		},
		{
			title = "Importancia",
			text = [=[Ninguna raza ha sufrido más por la traición de {link:deathwing}Alamuerte{/link} que los dragones rojos. Su cautiverio en {link:grim-batol}Grim Batol{/link} dio a la {link:horde}Horda{/link} sus dragones, y todavía es la causa del odio entre el Vuelo Rojo y los orcos del {link:dragonmaw-clan}clan Faucedraco{/link}.]=],
		},
		{
			title = "Los Aspectos",
			text = [=[En los días antiguos, cinco grandes dragones fueron elegidos para proteger el mundo. Alexstrasza, la mayor de ellos, fue nombrada guardiana de toda la vida. {link:deathwing}Neltharion{/link}, el Guardián de la Tierra, era su compañero. En la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, convenció a los Aspectos de que entregaran parte de su poder a su gran disco de oro, el Alma de {link:the-drag}Drag{/link}ón, y después lo volvió contra ellos. Los dragones quedaron dispersos y el Vuelo Rojo sufrió terriblemente. Alexstrasza nunca lo olvidó.]=],
		},
		{
			title = "Grim Batol",
			text = [=[En la {link:second-war}Segunda Guerra{/link}, el Alma de {link:the-drag}Drag{/link}ón cayó en manos de los {link:dragonmaw-clan}orcos Faucedraco{/link}. Con su poder capturaron a Alexstrasza y la ataron bajo la montaña de {link:grim-batol}Grim Batol{/link}, en {link:wetlands}Los Humedales{/link}. Se llevaban sus huevos a medida que los ponía, y criaban a sus crías como monturas de guerra. Los dragones rojos volaron para la {link:horde}Horda{/link} contra la {link:alliance}Alianza{/link}, quemando los bosques de {link:quel-thalas}Quel'Thalas{/link} y las ciudades del norte.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue elegida como Aspecto de la vida en los días antiguos.
• Fue traicionada por {link:deathwing}Neltharion{/link} en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.
• Fue mantenida cautiva por los Faucedraco en {link:grim-batol}Grim Batol{/link}.
• Fue liberada, y vio destruida el Alma de {link:the-drag}Drag{/link}ón.]=],
		},
		{
			title = "El presente",
			text = [=[Mucho después de la guerra, los Faucedraco aún retenían a la reina. {link:deathwing}Alamuerte{/link} fue a {link:grim-batol}Grim Batol{/link} a por sus huevos, con la intención de quedarse con sus hijos. Una pequeña banda de héroes y dragones liberó a Alexstrasza. El Alma de {link:the-drag}Drag{/link}ón fue destruida, y su poder regresó. Los dragones rojos se volvieron contra sus captores y expulsaron a Alamuerte. Los Faucedraco aún se aferran a {link:wetlands}Los Humedales{/link}, y los dragones rojos aún les dan caza. Dónde mora ahora la propia Reina Dragón, pocos mortales lo saben.]=],
		},
		{
			title = "Sin registro",
			text = [=[Las crónicas de los reinos dicen poco de adónde ha ido la Reina {link:the-drag}Drag{/link}ón desde su liberación.]=],
		},
	},
	bonds = {
		{ id = "deathwing", name = "Alamuerte", note = "su compañero Aspecto, y su traidor" },
		{ id = "queen-azshara", name = "Reina Azshara", note = "en cuya guerra fueron traicionados los Aspectos" },
	},
})

Translate("esES", "cenarius", {
	title = "Cenarius",
	subtitle = "Señor del bosque",
	allegiance = "Los bosques de Kalimdor · Círculo Cenarion",
	sections = {
		{
			title = "Resumen",
			text = [=[Cenarius fue un semidiós de la naturaleza salvaje, el señor de los bosques de {link:kalimdor}Kalimdor{/link}. Los {link:night-elves}elfos de la noche{/link} lo tenían por hijo de su diosa de la luna, Elune. Fue el maestro de {link:malfurion-stormrage}Malfurion Stormrage{/link} y el padre de las artes druídicas entre los mortales. Cayó en la {link:third-war}Tercera Guerra{/link}, muerto a manos de {link:grom-hellscream}Grom Hellscream{/link} en los bosques de {link:ashenvale}Vallefresno{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Todo druida que recorre el mundo sigue una senda que abrió Cenarius. El {link:cenarion-circle}Círculo Cenarion{/link}, que reúne a druidas elfos de la noche y {link:tauren}tauren{/link}, lleva su nombre. Su muerte fue una herida para los bosques de {link:kalimdor}Kalimdor{/link}, y los elfos de la noche no la han perdonado.]=],
		},
		{
			title = "El primer druida",
			text = [=[En la era anterior a la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, Cenarius moraba en las arboledas del {link:mount-hyjal}Monte Hyjal{/link}. Tomó al joven {link:malfurion-stormrage}Malfurion{/link} como alumno y le enseñó a moldear los poderes de la naturaleza. Cuando la {link:burning-legion}Legión Ardiente{/link} llegó a través del {link:well-of-eternity}Pozo de la Eternidad{/link}, Cenarius condujo a los antiguos espíritus del bosque a la batalla junto a los elfos de la noche. Tras la {link:great-sundering}Gran Fractura{/link}, los druidas de la orden de Malfurion adoptaron sus enseñanzas y las conservaron durante diez mil años. Su nombre perduró en el Cuerno de Cenarius, que Malfurion haría sonar un día al pie del Árbol del Mundo.]=],
		},
		{
			title = "Sus hijos",
			text = [=[Cenarius tuvo muchos hijos. Se dice que las dríades y los guardianes de la arboleda son suyos. Su hijo Zaetar fue el padre de los primeros centauros, una raza que hoy apenas recuerda de él más que su ira. Su hijo {link:keeper-remulos}Remulos{/link} guarda el claro sagrado de {link:moonglade}Claro de la Luna{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Enseñó a {link:malfurion-stormrage}Malfurion{/link} y a los primeros druidas los caminos de la naturaleza.
• Condujo a los espíritus del bosque en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.
• Veló por los bosques de {link:kalimdor}Kalimdor{/link} durante diez mil años.
• Combatió a los orcos que llegaron a talar los árboles de {link:ashenvale}Vallefresno{/link}.
• El cuerno que lleva su nombre convocó a los espíritus de los ancestros contra {link:archimonde}Archimonde{/link} en la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[En la {link:third-war}Tercera Guerra{/link}, los orcos del clan Grito de Guerra llegaron a {link:ashenvale}Vallefresno{/link} a talar madera. Los elfos de la noche lucharon contra ellos, y Cenarius acudió a defender su bosque. Los orcos no pudieron resistirle. En su desesperación, {link:grom-hellscream}Grom Hellscream{/link} y sus guerreros bebieron de un manantial contaminado por la sangre de {link:mannoroth}Mannoroth{/link}, y la vieja furia se apoderó de ellos. En esa furia mataron al semidiós. Cenarius está muerto. Sus druidas aún lo honran, y sus hijos aún guardan sus arboledas.]=],
		},
		{
			title = "Sin registro",
			text = [=[Si algún poder de Cenarius sobrevivió a su muerte, las crónicas no lo dicen.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "su alumno" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "su verdugo" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "hermano de su alumno" },
		{ id = "mannoroth", name = "Mannoroth", note = "cuya sangre enloqueció a sus verdugos" },
	},
})

Translate("esES", "kil-jaeden", {
	title = "Kil'jaeden",
	subtitle = "El Impostor",
	allegiance = "Legión Ardiente",
	aliases = { "Kil'jaeden el Impostor" },
	sections = {
		{
			title = "Resumen",
			text = [=[Kil'jaeden el Impostor es uno de los grandes señores de la {link:burning-legion}Legión Ardiente{/link}, sometido solo a la voluntad de {link:sargeras}Sargeras{/link}. En otro tiempo fue un líder de los eredar junto con {link:archimonde}Archimonde{/link}, y aceptó la oferta del titán oscuro como lo hizo Archimonde. Es un maestro de la mentira. Fue Kil'jaeden quien corrompió a los orcos de {red:draenor}Draenor{/red}, y fue él quien creó al {red:lich-king}Rey Exánime{/red}.]=],
		},
		{
			title = "Importancia",
			text = [=[Pocas de las calamidades de la última generación carecen de la mano del Impostor. A través de {link:ner-zhul}Ner'zhul{/link} y de {link:gul-dan}Gul'dan{/link} convirtió a los orcos en un arma. A través del Rey Exánime desató la {link:scourge}Plaga{/link} sobre {link:lordaeron}Lordaeron{/link}. A diferencia de {link:archimonde}Archimonde{/link}, nunca ha sido derrotado.]=],
		},
		{
			title = "Los eredar",
			text = [=[Hace mucho tiempo, los eredar eran gobernados por tres líderes: Kil'jaeden, {link:archimonde}Archimonde{/link} y Velen. {link:sargeras}Sargeras{/link} acudió a ellos con promesas de conocimiento y poder. Kil'jaeden y Archimonde aceptaron, y ellos y su pueblo fueron retorcidos hasta convertirse en demonios. Velen se negó, y huyó con sus seguidores. Kil'jaeden lo odió por ello, y juró perseguir al pueblo de Velen adondequiera que fuese.]=],
		},
		{
			title = "Los orcos",
			text = [=[El pueblo de Velen, los draenei, llegó por fin a Draenor, donde vivían los orcos. Kil'jaeden los encontró allí. Acudió al viejo chamán {link:ner-zhul}Ner'zhul{/link} con la apariencia de un espíritu de los ancestros, y le dijo que los draenei conspiraban contra su pueblo. Cuando Ner'zhul empezó a dudar de él, el Impostor recurrió a su aprendiz, {link:gul-dan}Gul'dan{/link}, y le enseñó las artes de la {link:fel-magic}magia vil{/link}. A través de Gul'dan dio a los orcos la sangre de {link:mannoroth}Mannoroth{/link}, los ató a la Legión y los lanzó contra los draenei.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Aceptó la oferta de {link:sargeras}Sargeras{/link} y se convirtió en un señor de la Legión.
• Engañó a {link:ner-zhul}Ner'zhul{/link} y volvió a los orcos contra los draenei.
• Enseñó a {link:gul-dan}Gul'dan{/link} las artes de la magia vil.
• Convirtió a Ner'zhul en el Rey Exánime.
• Envió al Rey Exánime a preparar {link:azeroth}Azeroth{/link} para la Legión.]=],
		},
		{
			title = "El Rey Exánime",
			text = [=[Cuando {link:ner-zhul}Ner'zhul{/link} huyó de la ruina de Draenor, Kil'jaeden lo estaba esperando. Arrancó el cuerpo del chamán y ató su espíritu a una armadura y un yelmo. Lo encerró en hielo y lo arrojó sobre {red:northrend}Rasganorte{/red}, con la orden de propagar una plaga que debilitara el mundo antes de la llegada de la Legión. El Rey Exánime así lo hizo. Cuando {link:archimonde}Archimonde{/link} cayó en el {link:mount-hyjal}Monte Hyjal{/link}, el Impostor supo que su siervo había empezado a soltarse de sus cadenas.]=],
		},
		{
			title = "Destino",
			text = [=[Kil'jaeden no ha puesto el pie en {link:azeroth}Azeroth{/link}. Tras la {link:third-war}Tercera Guerra{/link}, intentó que otros destruyeran al Rey Exánime. El Rey Exánime perdura, y el Impostor aún observa desde más allá del mundo.]=],
		},
		{
			title = "Sin registro",
			text = [=[Las crónicas no dicen dónde mora Kil'jaeden, ni qué planea ahora.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "su compañero señor de la Legión" },
		{ id = "sargeras", name = "Sargeras", note = "su amo" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "el chamán al que engañó y convirtió en el Rey Exánime" },
		{ id = "gul-dan", name = "Gul'dan", note = "su siervo entre los orcos" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "al que envió contra el Rey Exánime" },
	},
})

Translate("esES", "sargeras", {
	title = "Sargeras",
	subtitle = "Señor de la Legión Ardiente",
	allegiance = "Legión Ardiente",
	aliases = { "El Titán Oscuro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Sargeras es el amo de la {link:burning-legion}Legión Ardiente{/link}, un titán caído que busca deshacer toda la creación. En otro tiempo fue el mayor campeón de los titanes, los creadores de mundos, y combatió a los demonios del Vacío {link:fargodeep-mine}Abisal{/link} durante eras incontables. Con el tiempo perdió la esperanza en su obra. Liberó a los demonios que había encarcelado, los reunió en una hueste y la volvió contra cada mundo que los titanes habían formado.]=],
		},
		{
			title = "Importancia",
			text = [=[Cada guerra que la Legión ha librado en {link:azeroth}Azeroth{/link} se ha librado en nombre de Sargeras. Alcanzó el mundo tres veces: a través de la {link:queen-azshara}reina Azshara{/link}, a través de {link:aegwynn}Aegwynn{/link} y su hijo {link:medivh}Medivh{/link}, y a través de los orcos que ató a su voluntad. Su sombra está detrás de la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, de la {link:first-war}Primera Guerra{/link} y de la {link:third-war}Tercera Guerra{/link}.]=],
		},
		{
			title = "El titán caído",
			text = [=[Las historias dicen que Sargeras cazó demonios por la Gran Oscuridad durante más tiempo del que ningún mortal puede calcular. Lo que vio allí cambió su corazón. Llegó a creer que la propia creación era defectuosa y no podía repararse. Liberó a los demonios que había capturado, y corrompió a los eredar a través de {link:archimonde}Archimonde{/link} y de {link:kil-jaeden}Kil'jaeden{/link}, y así nació la Legión.]=],
		},
		{
			title = "Azeroth",
			text = [=[Hace diez mil años, la reina {link:azshara}Azshara{/link} y sus Altonatos atrajeron su mirada con el poder del {link:well-of-eternity}Pozo de la Eternidad{/link}. Sargeras envió a su Legión a través de su portal, y trató de entrar él mismo en el mundo. El Pozo fue destruido antes de que pudiera hacerlo. Eras después, se presentó ante la Guardiana {link:aegwynn}Aegwynn{/link} en medio de una gran tormenta en {red:northrend}Rasganorte{/red}. Ella mató a su avatar y selló su cuerpo en una tumba bajo el mar. Su espíritu se ocultó dentro de ella y pasó a su hijo aún no nacido. A través de {link:medivh}Medivh{/link}, el titán oscuro abrió el {link:dark-portal}Portal Oscuro{/link} y trajo a los orcos a {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue en otro tiempo el campeón de los titanes.
• Liberó a los demonios que había encarcelado y fundó la {link:burning-legion}Legión Ardiente{/link}.
• Corrompió a los eredar a través de {link:archimonde}Archimonde{/link} y {link:kil-jaeden}Kil'jaeden{/link}.
• Susurró a {link:azshara}Azshara{/link} y estuvo a punto de entrar en el mundo.
• Se ocultó dentro de {link:aegwynn}Aegwynn{/link} y de {link:medivh}Medivh{/link}, y abrió el {link:dark-portal}Portal Oscuro{/link} a través de él.]=],
		},
		{
			title = "Destino",
			text = [=[Sargeras nunca ha caminado por {link:azeroth}Azeroth{/link} en su verdadera forma. Su avatar yace en su tumba bajo el mar, que el brujo {link:gul-dan}Gul'dan{/link} alzó y en la que entró para encontrar su propia muerte. Cuando {link:medivh}Medivh{/link} murió, el dominio del titán oscuro sobre el mundo se quebró. Pero la Legión que dirige permanece, y sus señores no han renunciado a su hambre de este mundo.]=],
		},
		{
			title = "Sin registro",
			text = [=[Qué fue del espíritu de Sargeras cuando {link:medivh}Medivh{/link} murió, las crónicas de los reinos no saben decirlo.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "su lugarteniente" },
		{ id = "kil-jaeden", name = "Kil'jaeden", note = "su lugarteniente" },
		{ id = "aegwynn", name = "Aegwynn", note = "mató a su avatar" },
		{ id = "medivh", name = "Medivh", note = "su recipiente" },
		{ id = "queen-azshara", name = "Reina Azshara", note = "su sierva" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "recibió su don" },
	},
})

Translate("esES", "mannoroth", {
	title = "Mannoroth",
	subtitle = "El Destructor",
	allegiance = "Legión Ardiente",
	aliases = { "Mannoroth el Destructor" },
	sections = {
		{
			title = "Resumen",
			text = [=[Mannoroth el Destructor fue un señor del foso de la {link:burning-legion}Legión Ardiente{/link}, un demonio colosal de cuernos y colmillos. Dirigió los ejércitos de la Legión en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}. Más tarde, su sangre ató a los orcos de {red:draenor}Draenor{/red} a la Legión. Murió en {link:ashenvale}Vallefresno{/link} a manos de {link:grom-hellscream}Grom Hellscream{/link}, el primer {link:orcs}orco{/link} que la bebió.]=],
		},
		{
			title = "Importancia",
			text = [=[La maldición de los orcos fue la sangre de Mannoroth. Les dio fuerza y furia, y los convirtió en esclavos. Su muerte los liberó, y la {link:horde}Horda{/link} de {link:thrall}Thrall{/link} nació libre gracias a ella.]=],
		},
		{
			title = "La sangre",
			text = [=[En la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, Mannoroth dirigió a los demonios que entraron en tropel por el {link:well-of-eternity}Pozo de la Eternidad{/link}. Cuando la Legión se volvió hacia Draenor, el brujo {link:gul-dan}Gul'dan{/link} reunió a los jefes de los orcos y les ofreció un cáliz con la sangre del señor del foso. Grom bebió primero, y los demás lo siguieron. Su pueblo se convirtió en una {link:horde}Horda{/link} de furia atada a la voluntad de la Legión. Mucho después, Mannoroth llegó a {link:ashenvale}Vallefresno{/link} en la {link:third-war}Tercera Guerra{/link}. Cuando Grom y su clan Grito de Guerra desesperaron de vencer a los defensores del bosque, bebieron de un manantial que Mannoroth había contaminado con su sangre. En la furia que siguió, mataron a {link:cenarius}Cenarius{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirigió los ejércitos de la Legión en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}.
• Su sangre ató a los orcos de Draenor a la Legión.
• Contaminó un manantial en {link:ashenvale}Vallefresno{/link} y esclavizó por segunda vez al clan Grito de Guerra.]=],
		},
		{
			title = "Destino",
			text = [=[{link:thrall}Thrall{/link} y Grom fueron juntos a enfrentarse al señor del foso en un cañón de {link:ashenvale}Vallefresno{/link}. Mannoroth abatió a Thrall. Grom cargó solo y clavó su hacha en el pecho del demonio. Mannoroth murió, y la maldición de los orcos se rompió. Grom murió de sus heridas. El cañón todavía se llama {link:demon-fall-canyon}Barranco del Demonio{/link}.]=],
		},
	},
	bonds = {
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "el primero en beber su sangre, y su verdugo" },
		{ id = "gul-dan", name = "Gul'dan", note = "dio su sangre a los orcos" },
		{ id = "archimonde", name = "Archimonde", note = "su compañero señor de la Legión" },
		{ id = "cenarius", name = "Cenarius", note = "muerto por aquellos a quienes su sangre enloqueció" },
		{ id = "thrall", name = "Thrall", note = "luchó contra él junto a Grom" },
	},
})
